update content_bodies set title = 'イサバのカッチャ（魚市場のかあちゃん）', description = '戦後より八戸の台所として人々の暮らしに根付いている「いさば」。いさばとは魚市場のこと。陸奥湊駅前朝市も毎朝多くの人々で賑わいます。イサバのカッチャは働き者。暗いうちから働き始めます。そんな浜
の暮らしぶりを、生まれてからずっと朝市で買い物をしているというカッチャを通して紹介します。

出演：中山　央子
監督：山中　有
製作：青森県観光国際戦略局観光企画課' where id = 'lB_M9QRm1JSPxJrSe8jnN';
update content_bodies set title = 'Isaba no Katcha (Mother of the Fish Market)', description = 'Since the post-war period, ''Isaba'' has been rooted in the lives of people as the kitchen of Hachinohe. Isaba refers to the fish market. The morning market in front of Mutsu-Minato Station is bustling with many people every morning. The Katcha of Isaba is a hard worker. She starts working in the dark. Through Katcha, who has been shopping at the morning market since she was born, we introduce the lifestyle of the seaside.

Cast: Oko Nakayama
Director: Yu Yamanaka
Production: Aomori Prefectural Tourism International Strategy Bureau, Tourism Planning Division' where id = 'PhCtxlB9PHXGK-VHA8wN9';
update content_bodies set title = 'べこもち', description = '青森県の下北半島に伝わる伝統郷土菓子「べこもち」。
昔は節句などの行事の際にふるまわれるものでしたが、現在は日常的に愛食されています。
この作品は、べこもちができるまでの工程を映像のみで語ります。
切り口に美しい花模様があらわれる様子を、ぜひご覧ください。

出演：こすもす生活改善グループ
監督：山中　有
製作：青森県観光国際戦略局観光企画課' where id = '8LL54QmMCftoAk8s2_P-f';
update content_bodies set title = 'Beko Mochi', description = 'Beko Mochi is a traditional local sweet from the Shimokita Peninsula in Aomori Prefecture.
In the past, it was served during events such as festivals, but now it is enjoyed on a daily basis.
This work narrates the process of making Beko Mochi solely through visuals.
Please take a look at the beautiful floral patterns that appear on the cut surface.

Cast: Cosmos Lifestyle Improvement Group
Director: Yu Yamanaka
Production: Aomori Prefectural Tourism International Strategy Bureau, Tourism Planning Division' where id = 'tIhLEn4mraQEn9AWIkXWK';
update content_bodies set title = 'サナブリ', description = '青森県津軽地方では、田植えが終わると農休みに入り、集落の人々は安堵とともに豊作を願う儀礼として「サナブリ」と呼ばれる祭事を行います。
津軽地方の五所川原市相内の人々は、この祭事が昔から地域の人々の憩いのひと時であり、どれだけ心待ちにしていたかを語ります。苗を植えたばかりの田んぼに飛び込む場面も。

出演：三和　敏道
監督：山中　有
製作：青森県観光国際戦略局観光企画課' where id = 'tIj7OL4zmcFBXQatevNcM';
update content_bodies set title = 'Sanaburi', description = 'In the Tsugaru region of Aomori Prefecture, after the rice planting is completed, the farming community enters a break, and the people of the village hold a ceremony called ''Sanaburi'' as a ritual to express their relief and wish for a good harvest.
The people of Aikawa in Goshogawara City, Tsugaru region, speak of how this event has been a moment of relaxation for the community for generations and how eagerly they have awaited it. There is also a scene where they jump into the rice fields just after planting the seedlings.

Featuring: Toshimichi Miwa
Director: Yu Yamanaka
Production: Aomori Prefectural Tourism International Strategy Bureau, Tourism Planning Division' where id = 'P7eJ7WiHTZrH6S-AAvHOX';
update content_bodies set title = 'ホワイトインパルス', description = '青森空港は全国でも有数の豪雪地帯にあり、雪の多い年では類型降雪量が１０ｍを超える空港です。
民間航空機定期便が利8直する空港の中で、累計降雪量が１０ｍを超える空港は、全国でも稀です。
このような豪雪の青森空港を支えているのが、複数社の共同企業体により編成される青森空港除雪帯「ホワイトインパルス」です。' where id = '9u-jUEJVyjy53mAkffScv';
update content_bodies set title = 'White Impulse', description = 'Aomori Airport is one of the most heavy snowfall areas in the country, with cumulative snowfall exceeding 10 meters in years with significant snow.
Among airports with regular commercial airline services, it is rare for cumulative snowfall to exceed 10 meters.
Supporting Aomori Airport, which experiences such heavy snowfall, is the Aomori Airport Snow Removal Group "White Impulse," formed by a consortium of multiple companies.' where id = 'gfXadW42g7Ad4xDC8tRsk';
