update content_bodies set title = '【秋田市プロモーションビデオ①】自然の彩と隣人の温もりに富む「新波」', description = '雄物川が運んだ文化が花開く「新波」、秋にはこがね色の絨毯が広がる里「式田」。秋田市シティプロモーションモデル事業の一環として行ったワークショップを通し、地域住民が主体となってみつけたそれぞれの地区の『魅力』を詰め込んだ映像です。

～自然の彩と隣人の温もりに富む「新波」～
雨が降れば「洗濯もの入れておいて」と頼めるお隣さんがいて、何があっても助け合える。
春になれば一面緑、秋になれば黄金の波に心が明るくなる。
秋田市雄和・新波で、大切なことを見つけました。

【新波編ショートバージョン】https://youtu.be/XRoiXmMBKTo
【式田編」https://youtu.be/uGzoFvgbjLg
【式田編ショートバージョン】https://youtu.be/fdggJAytDJs' where id = 'CJTbcSyVlm-D_gx2oAX8q';
update content_bodies set title = '[Akita City Promotion Video ①] ''Shinami'' Rich in Nature''s Colors and Neighborly Warmth', description = '''Shinami'', where the culture brought by the Omorogawa River flourishes, and ''Shikida'', a village where a golden carpet spreads in autumn. This video is filled with the ''charm'' of each area discovered by local residents through workshops conducted as part of the Akita City City Promotion Model Project.

~ ''Shinami'' Rich in Nature''s Colors and Neighborly Warmth ~
When it rains, there''s a neighbor to ask, ''Could you please take in my laundry?'' and we can help each other no matter what happens.
In spring, everything turns green, and in autumn, the golden waves brighten our hearts.
In Akita City, Yuwa and Shinami, we found something important.

[Shinami Short Version] https://youtu.be/XRoiXmMBKTo
[Shikida Version] https://youtu.be/uGzoFvgbjLg
[Shikida Short Version] https://youtu.be/fdggJAytDJs' where id = 'pCeAAJF6JNqpx-IexIz9L';
update content_bodies set title = '【秋田市プロモーションビデオ③】よそものを大切にしてくれるまち「式田」', description = '雄物川が運んだ文化が花開く「新波」、秋にはこがね色の絨毯が広がる里「式田」。秋田市シティプロモーションモデル事業の一環として行ったワークショップを通し、地域住民が主体となってみつけたそれぞれの地区の『魅力』を詰め込んだ映像です。

～よそものを大切にしてくれるまち「式田」～
お金より大事な何かを探しに来た写真家。
長年の夢を追いかけにきたサラリーマン。
笑顔を運んでくれる、学生や若者たち。
まちが受け入れてくれる、大切にしてくれる。
秋田市河辺・式田で、大切なことを見つけました。

