update content_bodies set title = '[Akita City Promotion Video ③] A Town That Values Outsiders: ''Shikida''', description = 'In ''Shinami'', where the culture brought by the Omorogawa River flourishes, and in ''Shikida'', a village where a golden carpet spreads in autumn. This video is filled with the ''charm'' of each area discovered by local residents through workshops conducted as part of the Akita City City Promotion Model Project.

~ A Town That Values Outsiders: ''Shikida'' ~
A photographer who came to find something more important than money.
A salaryman who came to chase a long-held dream.
Students and young people who bring smiles.
The town welcomes and cherishes them.
In Akita City, Kabe and Shikida, we found something precious.

