update content_bodies set title = '大正寺おけさ', description = '大正寺おけさは、九州地方で継承されてきた「ハイヤ節」を起源とし、北前船により伝播されたと言われる貴重な民謡文化です。

日本遺産に登録されたストーリー「荒波を越えた男たちの夢が紡いだ異空間～北前船寄港地・船主集落～」の中で、物語を構成する文化財としても位置づけられています。
（秋田市観光振興課制作）' where id = 'NfXTNuoPE6bSuT0-0J-Ip';
update content_bodies set title = 'Taisho-ji Okesa', description = 'Taisho-ji Okesa is a precious folk culture that originated from the ''Haya-bushi'' passed down in the Kyushu region, and is said to have been propagated by the Kitamae ships.

It is also positioned as a cultural asset that constitutes the story registered as a Japanese heritage, ''The Dream of Men Who Overcame the Rough Waves Weaving an Otherworldly Space - The Port Towns and Shipowners of Kitamae.''
(Produced by Akita City Tourism Promotion Division)' where id = 'RVK99TeZGRyHVop6Pfla0';
update content_bodies set title = 'ダリアと菊の魅力をお届け！', description = '秋田中央地域地場産品活用促進協議会（通称「農家のパーティ」ネットワーク」では、JA秋田なまはげと管内の秋田市、男鹿市、潟上市が連携し、地場産品の活用促進と、3市の農林水産業と食品関連産業の振興を図ることを目的に、さまざまな活動を展開しています。

　このPRビデオは、3市で生産されるダリアと菊の生産現場の様子やその魅力を、3市の市長とJA秋田なまはげの組合長自らが皆さんにPRしています！' where id = 'EyWnzoGlFuWn8a_PRRR34';
update content_bodies set title = 'Delivering the Charm of Dahlias and Chrysanthemums!', description = 'The Akita Central Region Local Products Utilization Promotion Council (commonly known as the ''Farmers'' Party Network'') collaborates with JA Akita Namahage and the cities of Akita, Oga, and Katagami to promote the utilization of local products and to enhance the agricultural, forestry, and fisheries industries as well as the food-related industries in the three cities through various activities.

This PR video showcases the production sites of dahlias and chrysanthemums grown in the three cities, with the mayors of the three cities and the chairman of JA Akita Namahage personally promoting their charm!' where id = 'E8joI802HgmBVJcqpCHLa';
update content_bodies set title = '秋田市観光プロモーション動画「ライフ・イズ・ジャーニー」短編', description = '秋田市に住む夫婦の目線で描かれたドラマ仕立ての観光プロモーション動画「ライフ・イズ・ジャーニー」

