update content_bodies set title = 'ワォ！がたくさん あなたの知らない名古屋 オンラインツアー ナイトホッピング編', description = '2021年10月2日に開催した「ワォ！がたくさん　あなたの知らない名古屋オンラインツアー　ナイトホッピング編」のアーカイブです。
総合司会にはラジオパーソナリティーの”MEGURU”さんが、ガイド役にはBOYS AND MENの”田村侑久”、”勇翔”と、TEAM SHACHIの”秋本 帆華”、”咲良 菜緒”、”大黒 柚姫”、”坂本 遥奈”が、
名古屋の名物や地酒などをテーマに、名古屋の夜の観光として「居酒屋」めぐりを中心に名古屋を紹介。
あなたの知らない名古屋をご堪能ください。

