update content_bodies set title = 'Wow! A Lot of Things You Don''t Know About Nagoya Online Tour: Night Hopping Edition', description = 'This is the archive of the "Wow! A Lot of Things You Don''t Know About Nagoya Online Tour: Night Hopping Edition" held on October 2, 2021.
The overall host is radio personality "MEGURU," and the guides include "Yuki Tamura" and "Yuto" from BOYS AND MEN, as well as "Honoka Akimoto," "Nao Sakura," "Yuzuki Ooguro," and "Haruna Sakamoto" from TEAM SHACHI.
They introduce Nagoya through a tour focused on izakayas, themed around Nagoya''s specialties and local sake, showcasing the nightlife of Nagoya.
Enjoy the Nagoya you don''t know.

