update content_bodies set title = '【南海電鉄】「心、やすらぐ旅 高野山。」15秒Ver.', description = '世界遺産・高野山へは、南海電車で。
弘法大師・空海によって開かれた、高野山。
開創から1200年以上が経過した現代も、脈々とその教えが受け継がれる姿は、まさに「天空の聖地」。
都会の喧騒から離れ《高野山》とその《ふもと》で、心やすらぐひとときをお楽しみください。


