update content_bodies set title = '[Nankai Electric Railway] ''A Journey of Peace for the Heart - Mount Koya.'' 15-second Ver.', description = 'To the World Heritage Site of Mount Koya, take the Nankai train.

Mount Koya, founded by Kobo Daishi Kukai.

Even after more than 1200 years since its establishment, the teachings continue to be passed down, truly embodying the essence of a ''sacred place in the sky.''

Please enjoy a moment of peace in ''Mount Koya'' and its ''foothills,'' away from the hustle and bustle of the city.


――――――――――――――――――――――――――――

#WorldHeritage #MountKoya #NankaiRailway #Wakayama #MountKoyaTourism

