update content_bodies set title = '安全啓発アニメション第1弾 ～さちとの約束～（無理な踏切横断編）', description = 'このアニメは、大阪アニメーションカレッジ専門学校の学生さん達に協力していただき制作しました。 

警報器が鳴りだし、踏切内に入ると大変危険です。踏切では一旦立ち止まり安全を確認してわたりましょう。 
鉄道の安全利用にご協力お願いします。 

また、主人公の中松江　幸の声は中島 由貴さんに担当していただき 
