update content_bodies set title = 'Super Gifu Understanding TV "Ginan Illustration Art Exhibition"', description = 'Gifu Channel (Gifu Broadcasting) "Super Gifu Understanding TV"
Broadcasting on March 14, 2025 (Friday)

We introduce the "Ginan Illustration Art Exhibition" currently being held (from March 1 to March 31, 2025).
Fifteen members from the illustrator group "Gifu New Cultural Association" formed the "Ginan Illustration Art Town Development Committee" and are exhibiting their works.

The works are displayed at three locations: Ginan Town Library, Hotel Route Inn Ginan, and Ginan Town Hall.
Additionally, a stamp rally is being held that takes you around the three venues!
Those who collect stamps from all venues will receive a set of five illustration cards as a gift.

The gift of illustration cards is limited to the first 300 people, so those who collect all the stamps are encouraged to exchange them promptly at Ginan Town Hall or the library.

*This event utilizes the Ginan Town Proposal-type Collaborative Project Subsidy.

