===================================================' where id = 'HctVf7AkjAzK4KPoFLfAX';
update content_bodies set title = '鬼の住まう場所ー福知山・京都【大江町・観光PR動画】Fukuchiyama Kyoto/ Japan Travel Cinematic Vlog', description = '京都府福知山市の北部にある大江町。ここは古来より鬼の伝説が残る町として知られています。
今回、私たちはその大江町に数多く残されている鬼の痕跡を辿る旅をしてきました。
今も鬼が住むと伝えられる大江山、またその土地に残る文化や神話についても地元の方々にお話をうかがっています。
迫力満点のモニュメントや、美味しい食事にお酒、歴史ある伝統工芸など見所がたくさんあり、まだ知らない神秘の鬼伝説と暖かい地元の人情を体感できる町です。
福知山市を訪れた際は、ぜひ大江町へも足を運んでみてくださいね！

