update content_bodies set title = '東京青梅　観光PR「心躍る、春が来た」長編 ／ Ome City,Tokyo, Long ver.', description = '東京青梅　観光PR「都心から約1時間の別世界」
～心躍る、春が来た～長編 ／ Ome City,Tokyo, Long ver.

吉野梅郷梅まつり開催中！
期間：令和6年2月17日〜3月20日
詳細はこちら
https://www.omekanko.gr.jp/event/8659/

今回の動画は、春を迎えた青梅市で友人と待ち合わせ後、青梅を代表する梅や花しょうぶなどの美しい自然を感じながら散歩をしたり、ノスタルジックな場所をどきどきわくわくしながら巡ったり、青梅ならではの食も楽しんだりと、青梅の春を満喫する盛りだくさんの内容です。
おうち時間や通勤・通学、休憩時間に、ぜひお楽しみください。

【広がっています！Ome Blueサポーター】
Ome Blue（青梅ブルー）とは、青梅に住み、働き、活動するすべての方が、それぞれの立場の自由な発想で参加可能な地域プロモーションの取り組みです。
Ome Blueのロゴとカラーは青梅の自然・歴史・文化に根ざした「多彩な青梅の魅力」を表現しており、青梅を訪れる方がOme Blueに触れていただくことで、まちのファンになってもらえれば、という想いが込められています。
皆さんの生活や事業の中にさりげなく「Blue（青）」や「ロゴ」を取り入れて、一緒に青梅を盛り上げましょう！

ロゴのダウンロードや参加方法はＯｍｅ Ｂｌｕｅ公式ホームページをご覧ください。
https://www.city.ome.tokyo.jp/site/ome-blue/

