update content_bodies set title = 'Ome City, Tokyo, Long ver. - Tourism PR "Exciting, Spring has Come"', description = 'Ome City, Tokyo, Long ver. - Tourism PR "A Different World About an Hour from the City Center"
～Exciting, Spring has Come～ Long ver.

Yoshino Plum Village Plum Festival is currently being held!
