This video features a variety of content to enjoy spring in Ome City, including meeting friends, taking a walk while feeling the beautiful nature represented by plums and irises, exploring nostalgic places with excitement, and enjoying local cuisine unique to Ome. We hope you enjoy it during your time at home, commuting, or taking breaks.

【Expanding! Ome Blue Supporters】
Ome Blue is a community promotion initiative that allows everyone living, working, and engaging in activities in Ome to participate freely with their own ideas. The Ome Blue logo and colors express the "Diverse Charms of Ome" rooted in the nature, history, and culture of Ome, with the hope that visitors to Ome will become fans of the town by experiencing Ome Blue. Let''s subtly incorporate "Blue" and the "Logo" into your daily life and business to help promote Ome together!

