update content_bodies set title = '徳川家がつないだ千代田区×福井市', description = '【わがまち千代田429号】
家康公がつなげた福井市とのコラボ企画です。
千代田区では、かつて福井藩のあった場所をめぐり、
福井市では、家康公とその家族のゆかりの地を巡ります。
一年後には、北陸新幹線でつながる福井の魅力を、
歴史からグルメまでお届けします。

#千代田区
#福井市
#福井藩
#徳川家康公
#徳川家康' where id = 'k2d1mh-0f-k1ZjSwUp-Cu';
update content_bodies set title = 'Chiyoda Ward × Fukui City Connected by the Tokugawa Family', description = '[Our Town Chiyoda No. 429] 
This is a collaborative project with Fukui City, connected by Tokugawa Ieyasu. 
In Chiyoda Ward, we will explore the area that was once home to the Fukui Domain, 
and in Fukui City, we will visit places associated with Ieyasu and his family. 
A year later, we will deliver the charm of Fukui, connected by the Hokuriku Shinkansen, 
from history to gourmet experiences.' where id = 'ViDFdIJrIv9n6jH464gkT';
update content_bodies set title = '『FUKUI Style 蕎麦饗宴編』', description = '福井市イメージアップPR動画
『FUKUI Style』シリーズ公開1周年記念！
LDH kitchen THE TOKYO HANEDAにて
2025年10月14日（火）から始まる
『福いいネ！秋のランチフェア』の気になる内容は？

そこで──

今回の『FUKUI Style 蕎麦饗宴編』では
福井市食のPR大使を務める
橘ケンチさん（EXILE／EXILE THE SECOND）が
2025年12月6日（土）7日（日）
サンドーム福井で2デイズ公演を控える
中務裕太さん（GENERATIONS）を迎えて
『特製越前おろしそば』
『ソースカツ丼』
『福井県産梅使用 うめジュース』
こちらのフェアメニューをそれぞれ味わいます。

実は──

LDH所属グループ及びアーティストによる
動画視聴サービスCL（シーエル）にて
2025年夏に福井市内で収録された番組
『あちこちケンチ
～GENERATIONSと越前おろしそば頂上決戦～』
この番組内対決で考案～勝利を得た
橘ケンチさんのレシピを元に
THE TOKYO HANEDAの料理長が
特製越前おろしそばとしてブラッシュアップ、
今回の秋のランチフェアが実現しました。

ランチフェアの開催期間中
2025年10月14日（火）～11月24日（月）に
お近くへお立ち寄りの際はぜひご堪能ください。

さらに──

惜しくも次点となった
GENERATIONS特製越前おろしそばも
同じくTHE TOKYO HANEDA料理長がメニュー化、
GENERATIONSサンドーム福井公演を前に
2025年11月28日（金）～12月8日（月）の間
福井市観光物産館　福福館と越前蕎麦俱楽部で
