update content_bodies set title = '【かごしまサイクルツーリズム】ダイナミックな自然、豊かなグルメを楽しむ！大隅（おおすみ）ルートver2', description = '垂水港を拠点として8の字に周遊する壮大なルート。大隅半島は、豊かな自然に恵まれ農業をはじめ漁業、畜産など第一次産業が盛んな地域です。地域の資源を活用した体験や学習コンテンツに加えて、近海の鮮魚、黒毛和牛の産地ならではのグルメも揃います。緑深い高隈連山を背景に大平原が広がる、ダイナミックという言葉がよく似合う自然豊かなエリアです。' where id = '8BpO3LcnPYIRwyu0Y7W5P';
update content_bodies set title = '[Kagoshima Cycle Tourism] Enjoy Dynamic Nature and Rich Gourmet! Osumi Route ver2', description = 'A grand route that loops in a figure-eight from Tarumizu Port.
The Osumi Peninsula is blessed with rich nature and is an active region for primary industries such as agriculture, fishing, and livestock farming.
In addition to experiences and learning content utilizing local resources, you can also enjoy gourmet food unique to the area, such as fresh seafood from nearby waters and black-haired wagyu beef.
With the lush Takakuma mountain range in the background, it is a nature-rich area that truly embodies the word dynamic.' where id = '-EeQx33v5h9AsBtyWB22y';
update content_bodies set title = '【かごしまサイクルツーリズム】宇宙を身近に感じる！種子島ルートをサイクリング！', description = '種子島ルートでは、宇宙をより身近に感じられるエリアがあったり、南の島らしいサトウキビ畑が両側に広がる風景を見ながらサイクルできたりと、美しい海を臨むアイランドロードを存分に楽しめます。種子島の豊かな自然を満喫できるサーフィンやヨガなどのアクティビティも、一緒に体験してみてはいかがでしょうか。

#鹿児島 #サイクリング' where id = 'EFz6yLX5j47LeYmegnMk3';
update content_bodies set title = '[Kagoshima Cycle Tourism] Feel Closer to Space! Cycling the Tanegashima Route!', description = 'The Tanegashima Route offers areas where you can feel closer to space, and you can cycle while enjoying the scenery of sugarcane fields typical of southern islands on both sides, fully experiencing the island road with beautiful views of the sea. How about also trying activities like surfing and yoga to enjoy the rich nature of Tanegashima?' where id = 'iyKSvcZxx0Yt_U6PHCFee';
update content_bodies set title = '【かごしまサイクルツーリズム】日本の原風景を走る！北薩ルートをサイクリング！', description = '熊本県との県境に位置する北薩は、懐かしい里山の風景や風光明媚な温泉が楽しめる場所。白い砂浜が続く美しい海岸線では、東シナ海に沈むオレンジ色の夕日に癒されます。海の幸山の幸が豊かな北薩地域のご当地グルメも楽しみのひとつ！

#鹿児島 　#サイクリング' where id = 'DlQtMH_RmQAF8i94rgKkh';
update content_bodies set title = '[Kagoshima Cycle Tourism] Ride through Japan''s original landscapes! Cycling the North Satsuma Route!', description = 'North Satsuma, located on the border with Kumamoto Prefecture, is a place where you can enjoy nostalgic rural landscapes and scenic hot springs. The beautiful coastline with its white sandy beaches offers a soothing view of the orange sunset sinking into the East China Sea. One of the highlights is enjoying the local gourmet food from the North Satsuma region, rich in both seafood and mountain delicacies!

#Kagoshima  #Cycling' where id = 'lclaTZySOtwSB9QPPtiEz';
update content_bodies set title = '【かごしまサイクルツーリズム】薩摩藩が誇る武家の歴史と絢爛な文化が薫る街並みを走る！南薩ルート', description = '「サイクリングターミナルりんりん」をスタート・ゴール地点とするルート。南さつま市、日置市、鹿児島市、指宿（いぶすき）市、南九州市、枕崎市、それぞれの特徴的な風景を次々に楽しめます。リアス式の海岸線を背に沈みゆく夕日が美しい東シナ海、さらには桜島、開聞（かいもん）岳が聳え立つ錦江湾の美しさが格別です。武家屋敷群や薩摩焼窯元、焼酎酒蔵、鰹本枯れ節工場など魅力に満ち溢れたエリアです。

#鹿児島 #サイクリング' where id = 'GS8Qw8FNTAaRr51dRWva2';
update content_bodies set title = '[Kagoshima Cycle Tourism] Ride through the streets filled with the history of the samurai and the splendid culture of the Satsuma Domain! Minamisatsuma Route', description = 'This route starts and ends at the ''Cycling Terminal Rinrin''. You can enjoy the distinctive landscapes of Minamisatsuma City, Hioki City, Kagoshima City, Ibusuki City, Minamikyushu City, and Makurazaki City one after another. The beautiful sunset over the East China Sea, backed by the rias coastline, and the stunning views of Sakurajima and Kaimondake towering over Kinko Bay are exceptional. This area is filled with attractions such as samurai residences, Satsuma ware pottery studios, shochu distilleries, and katsuobushi (dried bonito) factories.' where id = '7AKvZmr3FkwEAKFteGOGJ';
update content_bodies set title = '【かごしまサイクルツーリズム】ダイナミックな自然、豊かなグルメを楽しむ！大隅（おおすみ）ルート', description = '垂水港を拠点として8の字に周遊する壮大なルート。大隅半島は、豊かな自然に恵まれ農業をはじめ漁業、畜産など第一次産業が盛んな地域です。地域の資源を活用した体験や学習コンテンツに加えて、近海の鮮魚、黒毛和牛の産地ならではのグルメも揃います。緑深い高隈連山を背景に大平原が広がる、ダイナミックという言葉がよく似合う自然豊かなエリアです。

#鹿児島 #サイクリング' where id = 'TeZj7ZAq1Esq1IfglLhPT';
update content_bodies set title = '[Kagoshima Cycle Tourism] Enjoy Dynamic Nature and Rich Gourmet! Osumi Route', description = 'A magnificent route that loops in a figure-eight from Tarumizu Port. The Osumi Peninsula is blessed with rich nature and is an active region for primary industries such as agriculture, fishing, and livestock farming. In addition to experiences and learning content utilizing local resources, you can also enjoy gourmet food unique to the area, such as fresh seafood from nearby waters and black wagyu beef. With the lush Takakuma mountain range in the background, this area is rich in nature and perfectly embodies the word ''dynamic.''

#Kagoshima #Cycling' where id = 'ttHK_7Wtqk7QQSZmz8sr-';
update content_bodies set title = '【かごしまサイクルツーリズム】霧島連山から豊かに流れ出す川沿いの風景を楽しむ！川内川（せんだいがわ）流域ルート', description = '吉松駅をスタートし、川内川沿いに高速船ターミナル（川内港）へ向かって走るルート。随所に溢れだす湧水池、東洋のナイアガラと呼ばれるダイナミックな曽木の滝、夏の風物詩の「ほたる」、東シナ海につながる河口まで川沿いに楽しみます。霧島山系の豊富な水に支えられる稲穂の田園、銘茶を産出する茶畑の風景がどこまでも広がります。

#鹿児島 #サイクリング' where id = '6fl-JwWHpIwIpWIonmvaT';
update content_bodies set title = '[Kagoshima Cycle Tourism] Enjoy the Scenic Views Along the Rivers Flowing Abundantly from the Kirishima Mountain Range! Sendai River Basin Route', description = 'Starting from Yoshimatsu Station, this route runs along the Sendai River towards the high-speed boat terminal (Sendai Port). Along the way, you can enjoy the bubbling spring water pools, the dynamic Sogi Falls, known as the Niagara of the East, the summer tradition of ''fireflies'', and the riverbank all the way to the estuary that connects to the East China Sea. The rich rice fields supported by the abundant water of the Kirishima mountain range and the landscapes of tea fields producing fine tea stretch endlessly.' where id = 'sy3l5PQsdctNehk6ak_Tc';
update content_bodies set title = '【かごしまサイクルツーリズム】宇宙を身近に感じる！種子島ルート', description = '#サイクリング，#鹿児島

種子島ルートでは、宇宙をより身近に感じられるエリアがあったり、南の島らしいサトウキビ畑が両側に広がる風景を見ながらサイクルできたりと、美しい海を臨むアイランドロードを存分に楽しめます。種子島の豊かな自然を満喫できるサーフィンやヨガなどのアクティビティも、一緒に体験してみてはいかがでしょうか。

その他の動画はこちらから
●日本の原風景を走る！北薩ルート
ＵＲＬ：https://youtu.be/_dVdz5snOOM
●歴史ロマンあふれる！甑島ルート
ＵＲＬ：https://youtu.be/3520T4qVl3w
●癒やしの自然で深呼吸！屋久島ルート
ＵＲＬ：https://youtu.be/-ZIpCm6Xka8' where id = 'FxTH6eAIU_8v6tH7fc8nn';
update content_bodies set title = '[Kagoshima Cycle Tourism] Feel Closer to Space! Tanegashima Route', description = '#Cycling, #Kagoshima

The Tanegashima Route offers areas where you can feel closer to space, and you can cycle while enjoying the scenery of sugarcane fields typical of southern islands on both sides, fully experiencing the island road with beautiful views of the sea. How about also trying activities like surfing and yoga to enjoy the rich nature of Tanegashima?

Other videos can be found here:
● Ride through Japan''s original landscapes! North Satsuma Route
URL: https://youtu.be/_dVdz5snOOM
● Overflowing with historical romance! Koshikijima Route
URL: https://youtu.be/3520T4qVl3w
● Breathe deeply in healing nature! Yakushima Route
URL: https://youtu.be/-ZIpCm6Xka8' where id = '9oFHRG06NyH2zOe3lcFCH';
update content_bodies set title = '【かごしまサイクルツーリズム】歴史ロマンあふれる！甑島ルート', description = '#サイクリング，#鹿児島

上甑島・中甑島・下甑島といちき串木野市を周遊するルート。サイクリングの醍醐味である、橋を渡る爽快感を存分に味わうことができます。古くは8000年前の地層が残る甑島の断崖、日本遺産に認定された、薩摩の武士が生きた町～武家屋敷群「麓」を歩く～の構成資産「里麓」「手打麓」、日本の近代化に貢献した薩摩スチューデントに学ぶ「薩摩藩英国留学生記念館」など、歴史ロマンあふれる旅をぜひ。

その他の動画はこちらから
●日本の原風景を走る！北薩ルート
ＵＲＬ：https://youtu.be/_dVdz5snOOM
●宇宙を身近に感じる！種子島ルート
ＵＲＬ：https://youtu.be/K-2gACI4ADU
●癒やしの自然で深呼吸！屋久島ルート
ＵＲＬ：https://youtu.be/-ZIpCm6Xka8' where id = 'TlDJE481H_5vRZMPosmG9';
update content_bodies set title = '[Kagoshima Cycle Tourism] A Route Full of Historical Romance! The Koshikijima Route', description = '#Cycling, #Kagoshima

A route that takes you around Upper Koshikijima, Middle Koshikijima, Lower Koshikijima, and Ichiki-Kushikino City. You can fully enjoy the refreshing feeling of crossing bridges, which is one of the delights of cycling. Experience the historical romance of Koshikijima, where cliffs with layers dating back 8,000 years remain, and walk through the town where Satsuma samurai lived, recognized as a Japanese Heritage site, including the ' where id = '5wHBcLBvVDApbDLjcAfDk';
update content_bodies set title = '【鹿児島県 本格焼酎PR】フランスのシェフ・ソムリエ開発の焼酎専用グラス', description = '鹿児島県及び鹿児島県酒造組合が連携し、フランス向け本格焼酎ＰＲ動画を制作。
動画には、現地シェフ・ソムリエが開発した焼酎専用グラスが登場します。
