update content_bodies set title = '美食編【どんどん味わいたくなる　かごしまのグルメ】', description = '農業＆畜産王国の鹿児島県は，安心・安全，ヘルシーで美味しいバラエティ豊かな食材の宝庫です。動画では，鹿児島出身のスポーツキャスターで、薩摩大使も務める、宮下純一氏が，鶏の旨味と醤油の甘味を味わうことができる鳥刺しと焼酎の無限ループで，鹿児島を代表するグルメを思う存分味わう模様を描き、鹿児島の食材の魅力を伝えています。温暖な気候で育まれた鹿児島のグルメをたくさん味わって，心も身体も健康になりましょう！' where id = 'Vou3Tsj55NZ_i6P5d83MP';
update content_bodies set title = 'Gourmet Edition: Kagoshima''s Cuisine That Makes You Want to Taste More', description = 'Kagoshima Prefecture, an agricultural and livestock kingdom, is a treasure trove of safe, healthy, and deliciously diverse ingredients. In the video, Junichi Miyashita, a sports caster from Kagoshima and also a Satsuma ambassador, showcases the experience of savoring Kagoshima''s representative gourmet dishes, including chicken sashimi that allows you to enjoy the umami of chicken and the sweetness of soy sauce, along with an endless loop of shochu. Let''s indulge in the deliciousness of Kagoshima''s cuisine, nurtured by its warm climate, and become healthy in both mind and body!' where id = 'vhLx_L3Nxx7zc6khaWhW_';
update content_bodies set title = '温泉編【どんどん癒されたくなる　かごしまの温泉】', description = '鹿児島県は100の温泉地があり，温泉の源泉数は2700カ所以上の全国2位，1日に2億2,500万リットル以上もの温泉が湧出する全国屈指の温泉王国です。世界的にも珍しい砂むし温泉のほか，県内各地に魅力的な温泉がたくさんあり，様々な泉質を楽しむことができるのも鹿児島の温泉の特徴です。動画では，鹿児島出身のスポーツキャスターで、薩摩大使も務める宮下純一氏が霧島温泉郷で癒されている模様を描き，鹿児島の温泉の魅力を伝えています。鹿児島の温泉でゆっくりして、心も身体も健康になりましょう！' where id = 'SuRvf84jSHwsoeL5X0MFZ';
update content_bodies set title = 'Onsen Edition: The More You Want to Heal, the More You’ll Love Kagoshima''s Hot Springs', description = 'Kagoshima Prefecture has 100 hot spring areas, ranking second in the nation with over 2,700 hot spring sources. It boasts one of the top hot spring kingdoms in Japan, with more than 225 million liters of hot spring water gushing out daily. In addition to the rare sand bath hot springs, there are many attractive hot springs throughout the prefecture, allowing visitors to enjoy a variety of water qualities, which is a characteristic of Kagoshima''s hot springs. The video features Junichi Miyashita, a sports caster from Kagoshima and also an ambassador for Satsuma, as he experiences relaxation in the Kirishima hot spring area, conveying the charm of Kagoshima''s hot springs. Let''s take a break in Kagoshima''s hot springs and become healthy in both mind and body!' where id = 'st9v_Y1tU_q5q2kqw90Ep';
update content_bodies set title = '東椎屋の滝', description = '日本の滝百選に選ばれた東椎屋の滝は、日光華厳の滝に似ているところから、「九州華厳」と称されています。高さ85mの断崖を落下する様は圧巻でマイナスイオンもいっぱいです。
　また、高貴端麗な名瀑で、滝つぼから流れ出る清流の渓谷、渓流の見事さもこの滝の特色です。清水に新緑の映える春、紅葉の秋ともに素晴らしい景観を誇っています。' where id = 'ZmpK47Dazk4oX6qshi7J_';
update content_bodies set title = 'Higashi Shiuya Falls', description = 'Higashi Shiuya Falls, selected as one of Japan''s top 100 waterfalls, is referred to as ''Kyushu Kegon'' due to its resemblance to Kegon Falls in Nikko. The sight of the water cascading down the 85-meter cliff is breathtaking, and it is filled with negative ions.
Additionally, it is a noble and beautiful waterfall, characterized by the clear stream flowing from the waterfall basin and the stunning beauty of the mountain stream. It boasts wonderful scenery in both spring, when the fresh greenery shines in the clear water, and autumn, when the leaves change color.' where id = 'WLzQLOwVDJOehYW3oHlGf';
update content_bodies set title = '長洲神社葵祭り', description = '長洲葵祭りは、毎年5月3日～5日まで行われる、長洲地区加茂神社のお祭りで、山の幸と海の幸の祭りです。
期間中は、コンコンチキリン♪の太鼓や笛の音にあわせて山車が長洲の町を練り歩きます。
宝暦11年(1761)豊前の国に疫病が起こり、それを鎮めるため、踊車として山車を奉納したのが起源とされています。
全盛期には、７基の山車があったそうで、現在は近年復活した「大西車組」と江戸時代からの伝統を受け継ぐ「上町車組」が山車２基を引き回し、無病息災や五穀豊穣を願います。' where id = 'I4c0HsRz4-9Jx2QAQ4BbS';
update content_bodies set title = 'Nagasu Shrine Aoi Festival', description = 'The Nagasu Aoi Festival is held every year from May 3rd to 5th at the Kamo Shrine in the Nagasu area, celebrating the blessings of the mountains and the sea.
During the festival, floats parade through the town of Nagasu to the sounds of drums and flutes playing ''Konkontikirin♪''.
The origin of the festival dates back to the 11th year of the Horeki era (1761), when a plague occurred in the Buzen province, and floats were dedicated as a form of dance to appease the spirits.
At its peak, there were said to be seven floats, and currently, two floats are pulled by the ''Onishi Float Group'', which was revived in recent years, and the ''Uemachi Float Group'', which carries on the traditions from the Edo period, wishing for good health and bountiful harvests.' where id = 'A89B3hsiJvtLDQyMgRdJJ';
update content_bodies set title = 'よっかいち「ひな祭り」', description = 'http://www.city.usa.oita.jp/site/kanko-event/8448.html

桜岡神社で神事を行った後、市内園児によるパレードが行われ、子ども雛がひな壇に上り、お内裏様やおひな様に扮した子どもたちのかわいらしい姿が訪れた人を楽しませてくれます。
その他にも、餅まきが行われ、カレーやお餅の販売も行われ、期間中は四日市商店街付近や桜岡神社にて、ひな人形も飾られます。' where id = 'hh39SlsqeFACW-IqPu5Ik';
update content_bodies set title = 'Yokkaichi ''Hinamatsuri''', description = 'http://www.city.usa.oita.jp/site/kanko-event/8448.html

After a Shinto ritual at Sakuraka Shrine, a parade by local kindergarten children takes place, where the children dressed as hina dolls ascend the hina platform, delighting visitors with their adorable appearances as they portray the Emperor and Empress.

Additionally, there will be a mochi throwing event, and sales of curry and mochi will be held. During the event period, hina dolls will also be displayed around the Yokkaichi shopping district and Sakuraka Shrine.' where id = '4UUNqB8dfCiUUgxB9THba';
update content_bodies set title = 'カチがあるまち宇佐「宇佐御勝印」完成までの手順', description = '宇佐市は、不滅の69連勝を成し遂げた昭和の大横綱双葉山や、全国4万社余りある八幡社の総本宮宇佐神宮がある「勝ちがあるまち」です。昨年度は、コロナ禍でも勝利のために一生懸命努力した、学生たちの青春に賭ける想いに寄り添い「一勝に賭けた青春」プロジェクトを実行し、今年の夏にはオリンピック・パラリンピック選手への必勝祈願をメッセージカードにして本市から届けました。

次は、そばにいる大切な人へ。

勝ちがあるまち宇佐に来て、身近にいる応援したい人の必勝祈願をし「御勝印」を届けよう！

〇宇佐御勝印完成まで
双葉の里と観光協会の2ヵ所を巡って「宇佐御勝印」を完成させます。

以下の場所で白紙の台紙をもらう（どちらの場所からスタートしても結構です）
双葉の里・・・宇佐市大字下庄269
宇佐市観光協会（宇佐神宮横）・・・宇佐市南宇佐2180-3

期間：令和3年10月1日（金曜日）～令和4年2月28日（月曜日）

さらに、抽選で69名様に5,000円相当のプレゼントがあたる期間限定キャンペーンを実施！！

〇キャンペーン応募方法
完成させた「宇佐御勝印」を施設職員に提示して応募券をもらい、必要事項を記入し、職員へお渡しください。
さらに、SNS（Instagram、Twitter、Facebook）に＃宇佐市＃宇佐御勝印 をつけて画像を投稿すると、応募口数が二口になるWチャンスがあります。

※SNSのみの参加も可能ですが、応募口数は一口となります。
    また、SNSへ投稿の際は「公開アカウント」に設定してください。

▽詳細はこちらから
https://www.city.usa.oita.jp/tourist/event/15634.html' where id = 'dFgBsV0nYrWy8m_gtF0sD';
update content_bodies set title = 'Steps to Complete the ''Usa Gokatsu-in'' in the Winning Town of Usa', description = 'Usa City is known as the ''town of victory,'' home to the legendary sumo wrestler Futabayama, who achieved an unbroken 69 consecutive wins, and the Usa Jingu, the head shrine of over 40,000 Hachiman shrines nationwide. Last year, despite the COVID-19 pandemic, we executed the ''Youth Betting on One Victory'' project, supporting the passionate efforts of students who worked hard for victory. This summer, we delivered message cards wishing for the success of Olympic and Paralympic athletes from our city.

Next, to your important person nearby.

Come to the winning town of Usa, pray for the success of those you want to support, and deliver the ''Gokatsu-in''!

〇 Completion of Usa Gokatsu-in
We will complete the ''Usa Gokatsu-in'' by visiting two locations: Futaba no Sato and the Tourist Association.

Receive a blank base paper at the following locations (you can start from either location):
Futaba no Sato...269 Shimosho, Usa City
Usa City Tourist Association (next to Usa Jingu)...2180-3 Minamiusa, Usa City

Period: October 1, 2021 (Friday) to February 28, 2022 (Monday)

Additionally, we are conducting a limited-time campaign where 69 lucky winners will receive gifts worth 5,000 yen!!

〇 How to Apply for the Campaign
Present the completed ''Usa Gokatsu-in'' to the facility staff to receive an application ticket. Fill in the required information and hand it back to the staff. Furthermore, if you post an image on social media (Instagram, Twitter, Facebook) with the hashtags #UsaCity #UsaGokatsuIn, you will have a double chance to enter the draw.

*Participation via social media only is also possible, but the number of entries will be one.
Also, please set your account to ''public'' when posting on social media.

▽ For more details, click here
https://www.city.usa.oita.jp/tourist/event/15634.html' where id = 'HnEqXg_hfV21-j9Mkq47I';
update content_bodies set title = 'それなら宇佐市！', description = '宇佐市は、2024住みたい田舎ベストランキング(人口5万人～10万人の部)において123自治体の中で、シニア部門で1位、子育て部門、若者・単身者部門、総合部門で2位を獲得しました。
「定住満足度日本一、交流満足度日本一のまち」へ向け、移住および子どもからシニアまで切れ目ない支援をご紹介しています。' where id = 'DNTby7S_4chnV7I3Bk0eZ';
update content_bodies set title = 'Then, Usa City!', description = 'Usa City ranked 1st in the senior category and 2nd in the child-rearing category, young people and single-person category, and overall category among 123 municipalities in the 2024 Best Rural Areas to Live Ranking (for populations between 50,000 and 100,000).
We introduce seamless support for migration and for everyone from children to seniors, aiming to become a city with the highest satisfaction in residency and interaction in Japan.' where id = 'xtnb3uYj3HbP-HMsGEiPM';
update content_bodies set title = '宇佐神宮紹介動画（英語字幕付）', description = '大分県ガールスカウト第５団が制作した宇佐神宮を紹介する動画です。ベースの映像は２年前に制作したものですが、今回、福岡・大分デスティネーションキャンペーンの開催にあわせ、インバウンド用に英語の字幕を入れ再編集しました。ガールスカウトのメンバーが宇佐神宮の魅力を分かりやすく紹介しています。' where id = 'Mapf431irPolp8Xf7xXMS';
update content_bodies set title = 'Introduction Video of Usa Jingu Shrine (with English Subtitles)', description = 'This is a video introducing Usa Jingu Shrine produced by the Oita Prefecture Girl Scouts, Troop 5. The base footage was created two years ago, but this time, in conjunction with the Fukuoka-Oita Destination Campaign, it has been re-edited with English subtitles for inbound visitors. The Girl Scouts members clearly present the charm of Usa Jingu Shrine.' where id = '_8jLDO2AZFFFOWCiz5Baz';
