update content_bodies set title = '宇佐高生制作動画「宇佐の偉人 南一郎平って？？？」', description = '宇佐高等学校では、総合的な探求の時間において、これからの時代に求められる創造力を生かした課題解決の手法「デザインシンキング」について学んでおり、その一環としてショート動画の制作が行われました。
宇佐市や宇佐高等学校の魅力を伝える様々な動画の中には南一郎平に関するものもあり、NHK朝ドラ「南一郎平」誘致推進協議会から資料の提供を受ける等、宇佐の歴史を学びながら制作をされていました。
とても楽しい動画になっていますので是非一度ご覧ください。' where id = 'Q_DlCWuWdkVJ72xg6yhq1';
update content_bodies set title = 'Usa High School Student-Made Video: Who is Ichirohei Minami???', description = 'At Usa High School, students are learning about a problem-solving method called ''Design Thinking,'' which utilizes creativity required for the future, during their comprehensive inquiry time. As part of this, they created short videos.
Among the various videos that convey the charm of Usa City and Usa High School, there are some related to Ichirohei Minami. They received materials from the NHK morning drama ''Ichirohei Minami Promotion Council'' and learned about the history of Usa while producing the videos.
It has turned out to be a very enjoyable video, so please take a look!' where id = '7gDhzuvOAkNP4VaAwcAXC';
update content_bodies set title = '宇佐神宮ユニバーサルツーリズム動画', description = '宇佐市では、高齢や障害の有無に関わらず誰もが気兼ねなく安心して観光を楽しんでもらえる「ユニバーサルツーリズム」の推進に取り組んでいます。
　今回、ＮＰＯ法人自立支援センターおおいたと連携し、宇佐神宮御鎮座1300年観光振興プロジェクトの一環として、車いす等で参拝する場合のコースや観光ポイントなどをまとめた動画を作成しました。' where id = 'TJmJZstnC-LVP2hToJ3fb';
update content_bodies set title = 'Usa Jingu Universal Tourism Video', description = 'Usa City is working to promote ''Universal Tourism'' so that everyone, regardless of age or disability, can enjoy sightseeing with peace of mind.
This time, in collaboration with the NPO Oita Support Center, we created a video summarizing the courses and sightseeing points for worshiping with a wheelchair as part of the Usa Jingu 1300th Anniversary Tourism Promotion Project.' where id = '8_2lhLr4tC7vwHzzP9Nul';
update content_bodies set title = '白浜温泉 献湯祭＜お湯の恵みに感謝する＞', description = '町内に源泉を持つ温泉会社8社と町の観光関係者が
朝一番に源泉からくみ上げた「一番湯」を入れた樽を担いで温泉街を練り歩き、山神社に移動します。神社では、巫女から神職へと順番に手渡して神社に奉納する神事を行います。

令和６年度の第38回献湯祭では
奈良時代の衣装を参加希望者が着て行列が行われます。
衣装を身にまとって白浜温泉街から山神社まで歩きます。
神事の最後には和歌山名物「餅まき」もあります。地元のお祭りに参加することは、その地域の文化をより深く理解し、地元の人々とのつながりを感じる素晴らしい機会となります。

#南紀白浜  #白浜観光  #白浜観光  #献湯祭 #温泉' where id = 'ieWCgKNLQzDBuL7E2to34';
update content_bodies set title = 'Shirahama Onsen Kentyōsai <A Celebration of Gratitude for the Blessings of Hot Springs>', description = 'Eight hot spring companies with their own sources in the town and local tourism officials
will carry a barrel filled with the "first hot spring water" drawn from the source early in the morning
and parade through the hot spring town to Yamajinja Shrine. At the shrine, a ritual will be conducted
where the water is handed over in turn from the shrine maidens to the priests for dedication.

In the 38th Kentyōsai of the 6th year of Reiwa,
participants wishing to join will wear costumes from the Nara period and form a procession.
They will walk from Shirahama Onsen town to Yamajinja Shrine in their costumes.
At the end of the ritual, there will also be a traditional "mochi-maki" (rice cake throwing),
a local specialty of Wakayama. Participating in this local festival is a wonderful opportunity
to gain a deeper understanding of the region''s culture and feel a connection with the local people.

#NankiShirahama  #ShirahamaTourism  #ShirahamaTourism  #Kentyōsai #Onsen' where id = 'EOU8SIMm36KEdVUUjTGlo';
