update content_bodies set title = 'June 14, 2024', description = 'Things you need to know before going to China 🇨🇳

In China, you can''t use Google or Line, which we usually rely on...
If you don''t know about the restrictions, you might find yourself unable to do anything once you arrive.

That''s when a VPN comes in handy, but the real winner is an eSIM with VPN.
With this, you can use the internet as usual and have unlimited data.

The eSIM I used this time is called Holafly.

There''s a coupon code available, so if you''re interested, definitely give it a try!
Coupon code:
"shumpei-trip"
