島興師（しまおこし）たちのこんな本音を聞きたかった! 
奄美群島における島のモノゴトの可能性にチャレンジ!! 
次世代につなぐ島ンチュによる悪戦苦闘のプレゼンテーション形式トークイベント!? 

▶︎ 島サバクリエイティヴGCDとは
奄美群島人材育成成果発表会「島サバクリエイティヴGCD（ガシド）」とは、奄美群島においてチャレンジしている方々にスポットを当てたもので、奄美群島における島の物事の可能性にチャレンジしている方々にご登壇いただき、それぞれの方が現在取り組んでいる事やその過程での苦労話、あるいは、奄美に対する想いなどをお話いただくトークショーとなっております。

▶︎ 令和６年度報告者
沖永良部（和泊町）サバクリ：private dining 陽-haru-  オーナー 後藤 健太
沖永良部（知名町）サバクリ：一般社団法人シマスキ代表 窪田 貴史
沖永良部（知名町）サバクリ：全国高等学校総合文化祭８年連続出場 沖永良部高校エイサー部
徳之島（天城町）サバクリ：天城エイエイオー祭り主催者 麓 正高
与論（与論町）サバクリ：NPO法人海の再生ネットワークよろん事務局長 池田 香菜
喜界（喜界町）サバクリ：KHK（喜界島放送協会）代表／HYOS（映像制作）代表 泰田 博也
奄美（宇検村）サバクリ：宇検村 企画観光課 マット・プライド
奄美（奄美市）サバクリ：学生団体Annacoto 元平 結凪／城 音羽／安田 琉夏 
※敬称略

▶︎ 奄美群島チャレンジ商品展示販売会
・タートルベイ醸造株式会社
奄美、鹿児島、沖縄の酒造メーカーと
コラボで、焼酎、泡盛等のソーダ割り、
缶ハイボールを製造しています。
・プリン専門店 che ～プリンカクメイ～
ラテンアメリカで食べた固めのプリンを
意識し、奄美の食材を使用したこだわりの
プリンを作っています。
・一般社団法人E-Yoron
漂着した海洋プラスチックごみ、
島内で消費された廃プラスチックごみで
アップサイクルを始めました。
・一般社団法人おきのえらぶ島観光協会
島内最大級の品数のお土産販売所を
併設しております。
おきのえらぶの最先端がここに集結!
・奄美群島振興開発基金
奄美群島の産業振興を支援する
政策金融機関として、組織内外に
情熱をもって示し活動しています。

