update content_bodies set title = 'けふの下呂温泉', description = '２月25日（土）の『冬の下呂温泉花火物語』打ち上げの様子です。

当日は雨や風もなく絶好の花火日和、『合格祈願花火』がテーマの。
5段打上花火が夜空に広がりました。

毎週の恒例行事に思える花火も、気づけば3月25日（土）の最後の打ち上げまで、
あと4回となってしまいました。
終わってしまうのは寂しい限りですが、1回1回を目に焼き付けていきたいですね。

今後とも、下呂温泉をよろしくお願いいたします。

#下呂温泉 #日本三名泉 #下呂市 #下呂観光  #花火物語 #下呂大橋 #飛騨川' where id = 'rn0VKDxYQuY2gP5V3FUGv';
update content_bodies set title = 'Today''s Gero Onsen', description = 'This is a glimpse of the ''Winter Gero Onsen Fireworks Story'' held on February 25th (Saturday).

The weather was perfect for fireworks with no rain or wind, themed around ''Fireworks for Success Prayers''.
Five-tiered fireworks spread across the night sky.

What seems like a weekly tradition of fireworks has now dwindled down to just 4 more launches until the final one on March 25th (Saturday).
While it’s sad that it will come to an end, I want to engrave each moment in my memory.

We appreciate your continued support for Gero Onsen.

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #FireworksStory #GeroBridge #HidaRiver' where id = 'ZHWEeGofcqUJV-K3pNnRF';
update content_bodies set title = 'けふの下呂温泉', description = '２月４日（土）の、『冬の星座花火』の様子です。

当日は寒さは厳しいものの雨や雪はなく、絶好の花火日和でした。
澄み切った夜空に、星をイメージした花火が打ち上がりました。
星に負けず劣らずのきれいな花火がお客様を魅了していました。

三寒四温といいますが、少しづつ暖かい日が増えてきたように思えます。

今後とも、下呂温泉をよろしくお願いいたします。

#下呂温泉 #日本三名泉 #下呂市 #下呂観光  #花火物語 #下呂大橋 #飛騨川 #星座' where id = 'bHV_UfekohhUgRcvC06Wq';
update content_bodies set title = 'Today’s Gero Onsen', description = 'On February 4th (Saturday), we experienced the ''Winter Constellation Fireworks''.

Although it was quite cold on the day, there was no rain or snow, making it a perfect day for fireworks.
Fireworks inspired by stars lit up the clear night sky.
The beautiful fireworks, rivaling the stars, captivated our guests.

As the saying goes, ''three cold days and four warm days'', it seems that warmer days are gradually increasing.

We appreciate your continued support for Gero Onsen.

#GeroOnsen #Japan''sThreeFamousHotSprings #GeroCity #GeroTourism #FireworksStory #GeroBridge #HidaRiver #Constellation' where id = 'ipmfagJU_xaD_JxEN9bTk';
update content_bodies set title = 'けふの下呂温泉', description = '1月21日（土）の『冬の下呂温泉花火物語』の様子です。

大寒の終わりを、温かみのある色調の花火で表現した「春よ来い来い・寒明け花火」がテーマです。
とても寒い夜でしたが、花火を見に多くのお客様がいらっしゃいました。

新年からあっという間に3週間が経ち、下呂温泉も始動をはじめています。
昨年よりも、もっと素晴らしい下呂温泉を皆様に体験いただけますように、
頑張っていきます。

今週末の1月28日（土）にも花火は打ち上がりますので、ぜひご覧にいらっしゃってください。

今後とも、下呂温泉をよろしくお願いいたします。


#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #花火物語 #下呂大橋 #飛騨川' where id = 'WK45MZej8qABG0REtBS3m';
update content_bodies set title = 'Today''s Gero Onsen', description = 'This is a glimpse of the ''Winter Gero Onsen Fireworks Story'' held on January 21st (Saturday).

The theme is ''Spring, Come! Come! - The Fireworks of the End of Cold'', expressed through warm-colored fireworks to mark the end of the Great Cold.
It was a very cold night, but many guests came to see the fireworks.

Three weeks have passed since the New Year, and Gero Onsen is starting to get into full swing.
We will do our best to provide everyone with an even more wonderful experience at Gero Onsen than last year.

Fireworks will also be launched this weekend on January 28th (Saturday), so please come and enjoy them.

Thank you for your continued support of Gero Onsen.

#GeroOnsen #Japan''sThreeFamousHotSprings #GeroCity #GeroTourism #FireworksStory #GeroBridge #HidaRiver' where id = 'hxEBFjryuDLZSfqjyzygr';
update content_bodies set title = 'けふの下呂温泉', description = '５月21日（土）、「ラブレター花火」をテーマとする『天壌無窮　悪疫退散　下呂温泉花火』が
開催されました。

当日は雨に見舞われたものの、開始時間にはすっかり小ぶりになり、無事に花火が打ち上がりました。
テーマの通り、情熱的に打ち上がる花火にお客様たちは歓声をあげ、終わりごろには盛大な拍手が巻き起こっていました。
来週も、もっともっと多くのお客様に来ていただきたいですね。

もちろん、温泉を堪能するのもお忘れなく。
アルカリ性のお湯ですべすべのお肌を手に入れてください。

下呂温泉をよろしくお願いいたします！

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火' where id = 'sh43SBAmPRy7Lsfnum_G5';
update content_bodies set title = 'Today’s Gero Onsen', description = 'On May 21st (Saturday), the ''Tenjo Mukyu - Epidemic Extermination - Gero Onsen Fireworks'' themed ''Love Letter Fireworks'' was held.

Although it rained on the day, the rain had significantly lessened by the start time, and the fireworks were successfully launched.
In line with the theme, the passionately launched fireworks drew cheers from the audience, and by the end, there was a resounding applause.
We hope to welcome even more guests next week.

Of course, don’t forget to enjoy the hot springs as well.
Please indulge in the alkaline waters for smooth skin.

Thank you for your support of Gero Onsen!

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks' where id = 'qFjMwPNbzWfs39nMQRLM8';
update content_bodies set title = 'けふの下呂温泉', description = '５月14日（土）、『天壌無窮　悪疫退散　下呂温泉花火』が久しぶりに開催されました。

やや肌寒い夜風が吹いていましたが、多くのお客様が花火を見に集まってくださいました。
躍動感あふれる『こいのぼり花火』に歓声があがり、下呂温泉の夜が活気に満ちていました。

天候が安定しないこの頃ですが、来週も雨に見舞われずに花火を鑑賞したいですね。

もちろん、花火見物の後は温泉もお忘れなく。
しらさぎ緑地公園内の『噴泉池』の足湯に浸かるのもいいですね。

下呂温泉をよろしくお願いいたします！

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火 #こいのぼり #噴泉池' where id = '64KS3DMt0gYvOvyTLlMpi';
update content_bodies set title = 'Today’s Gero Onsen', description = 'On May 14th (Saturday), the ''Eternal Heaven and Earth, Epidemic Dispersal, Gero Onsen Fireworks'' was held for the first time in a while.

Although a slightly chilly night breeze was blowing, many guests gathered to watch the fireworks.
Cheers erupted at the dynamic ''Koinobori Fireworks,'' filling the night of Gero Onsen with excitement.

The weather has been unstable lately, but we hope to enjoy the fireworks next week without being caught in the rain.

Of course, don’t forget to enjoy the hot springs after watching the fireworks.
Soaking in the foot bath at the ''Funsen Pond'' in Shirakagi Green Park is also a nice option.

Thank you for your support of Gero Onsen!

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks #Koinobori #FunsenPond' where id = 'fQHv-OFbxXjng6IcuPieG';
update content_bodies set title = 'けふの下呂温泉', description = '４月2日（土）の、『新生活応援花火』がテーマの『天壌無窮　悪疫退散　下呂温泉花火』の様子です。

新年度となって初めての花火は、見事にお客様たちを魅了していました。
これから始まる新生活への、応援であったかのようでした。
気温もぐっと春めいてきていて、そろそろ暖房ともお別れの時期かもしれませんね。

暖房とはお別れしても、温泉とは四季を通してお付き合いしたいものです！
生活が変化するこの時期こそ、温泉に浸かって体調を整えましょう！

下呂温泉をよろしくお願いいたします！


#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火' where id = '6RKeMhm-R-MliOeqaS1Po';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On April 2nd (Saturday), the ''Heaven and Earth Eternal, Epidemic Extermination, Gero Onsen Fireworks'' themed ''New Life Support Fireworks'' took place.

The first fireworks of the new fiscal year beautifully captivated the guests.
It felt like a support for the new life that is about to begin.
The temperature has also become quite spring-like, and it might be time to say goodbye to heating soon.

Even if we part ways with heating, we want to maintain our relationship with the hot springs throughout the seasons!
During this time of change in life, let''s soak in the hot springs to keep our health in check!

Thank you for your support of Gero Onsen!

#GeroOnsen #Japan''sThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks' where id = 'psNAoMlLAoZHNAuy-qIGH';
