#Nakatsugawa #GeroOnsen #Tourism' where id = '3HIwlpC5qaiB5qZD1c63l';
update content_bodies set title = 'けふの下呂温泉', description = 'まれにみる大雪の下呂温泉、雪化粧をした合掌村を見に行こうと向かってみました。

いつも見慣れたはずの合掌村は一面の銀世界。
まるで別の場所のようにも見えます。
手湯と足湯で体を暖めながら、雪道を歩いてみました。

雪で覆われた合掌家屋は雰囲気抜群で、いつも以上に堪能できました。
さすがにすべり台は使用できませんでしたが、これから毎日……というには雪かきが大変ですが、
たまにはこうした姿の合掌村に触れるのも楽しいものですね。

こんな雪の日には温泉が一番！
下呂温泉の湯船に浸かって新年への英気を養いましょう！

下呂温泉をよろしくお願いいたします！

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #合掌村' where id = 'Z1qX465rUyPDVbCRDGUv6';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Gero Onsen, covered in rare heavy snow, I headed out to see the gassho village dressed in snow.

The gassho village, which I usually see, is a world of silver.
It looks like a completely different place.
I walked along the snowy path while warming my body in the hand and foot baths.

The gassho houses covered in snow have an exceptional atmosphere, and I was able to enjoy it more than usual.
Although the slide was not usable, it would be quite a task to shovel snow every day...
But it’s fun to experience the gassho village in this form once in a while.

On a snowy day like this, hot springs are the best!
Let’s soak in the Gero Onsen and recharge our spirits for the new year!

Thank you for your support of Gero Onsen!

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GasshoVillage' where id = 'JZS4fcNoTTgTTXqzukYdB';
update content_bodies set title = 'けふの下呂温泉', description = '12月11日（土）に、「歳末感謝花火」がテーマの、『天壌無窮悪疫退散　下呂温泉花火物語』が開催されました。

寒い中にも多くのお客様がいらっしゃり、打ち上がる花火に歓声を上げていました。
今年も残すところあと少し、締めくくりと来年へ向けての準備を進めていきたいですね。

『花火物語』が開催されている緑地公園では、ウィンターイルミネーションも点灯していました。
ロマンティックな雰囲気で、こちらにもお客様の姿が見えました。

寒さが一層増す今日この頃、温泉がますます恋しくなってきますね！
下呂温泉をよろしくお願いいたします！

下呂温泉観光協会HP
↓
https://www.gero-spa.com/topics/detail_326.html

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火' where id = 'UYEd042iZs2CSPVGaDr15';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On December 11th (Saturday), the ''Year-End Appreciation Fireworks'' themed event, ''Tenjo Mukyu, Evil Spirits Dispersed: Gero Onsen Fireworks Story,'' was held.

Despite the cold, many guests came to enjoy the fireworks, cheering as they lit up the sky.
With only a little time left this year, we want to prepare for the end and for the coming year.

At the green park where the ''Fireworks Story'' is being held, winter illuminations were also lit up.
In a romantic atmosphere, we could see guests enjoying the scene.

As the cold intensifies these days, the longing for hot springs grows stronger!
We appreciate your support for Gero Onsen!

Gero Onsen Tourism Association HP
↓
https://www.gero-spa.com/topics/detail_326.html

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks' where id = 'AXDPm-l3JKXuY10tPbr9I';
update content_bodies set title = 'けふの下呂温泉', description = '１１月27日（土）の、『スイーツ花火』の様子です。
今回も多くのお客様にお越しいただき、スイーツをテーマにしたパステルカラーの花火に歓声が上がっていました。

見ていたら、なんだかスイーツが食べたくなってきました。
下呂温泉にはたくさんのスイーツがそろっていますので、ぜひご賞味ください。

気づけば11月も終わり、12月に入ろうとしています。
『天壌無窮悪疫退散　下呂温泉花火物語』は3月まで開催の予定ですので、まだまだ楽しむことができますね。

下呂温泉をよろしくお願いいたします！

下呂温泉観光協会HP
↓
https://www.gero-spa.com/topics/detail_326.html

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火 #素肌美人スイーツ #スイーツ' where id = 'zccNMiYPhmSYYPtOcLUq4';
update content_bodies set title = 'Today''s Gero Onsen', description = 'This is a glimpse of the ''Sweets Fireworks'' held on Saturday, November 27th.
Once again, many guests came to enjoy the pastel-colored fireworks themed around sweets, and cheers erupted.

Watching them made me crave some sweets.
Gero Onsen has a variety of sweets available, so please be sure to try them.

Before we knew it, November is coming to an end, and December is just around the corner.
The ''Tenjo Mukyu, Evil Plague Dispersal, Gero Onsen Fireworks Story'' is scheduled to run until March, so there’s still plenty of enjoyment to be had.

Thank you for your support of Gero Onsen!

Gero Onsen Tourism Association HP
↓
https://www.gero-spa.com/topics/detail_326.html

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks #BeautifulSkinSweets #Sweets' where id = 'kuYdo8AzLNMyo1BwWPTyy';
update content_bodies set title = 'けふの下呂温泉', description = '先週に撮影してきた、『岩屋ダム周辺』、『孝子ヶ池公園』、『玉龍寺』の紅葉の様子です。

晴れ間の下、色鮮やかな紅葉が見れましたが、同時に落葉も目立ち始めていました。
紅葉は寒くなると一気に葉が落ちてしまうと言われていますが、ここ数日の冷え込みで
今回の紅葉も落ちてしまっているかもしれませんね。

温泉街から見える山々の頂上にも雪が見え、秋から冬への移り変わりを告げているかのようでした。

こんな時こそ、温泉で体を暖めて備えましょう！
下呂温泉をよろしくお願いいたします！

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #紅葉 #岩屋ダム #孝子ヶ池 #玉龍寺' where id = 'rTGkC0jmsdlwN-kQBulBp';
update content_bodies set title = 'Today''s Gero Onsen', description = 'Here are the autumn leaves I photographed last week around ''Iwaya Dam'', ''Takako Pond Park'', and ''Gyokuryuji Temple''.

Under the clear skies, the vibrant autumn leaves were visible, but at the same time, the fallen leaves were starting to stand out.
It is said that the leaves fall rapidly when it gets cold, and with the recent drop in temperature, this year''s autumn leaves may have already fallen as well.

Snow was visible on the peaks of the mountains seen from the hot spring town, as if announcing the transition from autumn to winter.

Now is the time to warm up your body in the hot springs and prepare!
Thank you for your support of Gero Onsen!

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #AutumnLeaves #IwayaDam #TakakoPond #GyokuryujiTemple' where id = 'oAr8vetfourAWsr1l08-T';
update content_bodies set title = 'けふの下呂温泉', description = '１１月２０日（土）に開催された、「天壌無窮　悪疫退散　下呂温泉花火物語」は、『勤労感謝花火』がテーマでした。

明日、11月23日（火）の勤労感謝の日を先取りしたもので、生活を支える勤労・生産に感謝（３・９）
して、盛大な花火が打ち上がりました。
この日は、もともとは新嘗祭（にいなめさい）と呼ばれる五穀豊穣に感謝するお祝いが元という
説があるそうです。
収穫への感謝が勤労へのものに変わったのにも諸説があるそうですが、めぐりめぐってこうして花火を楽しめるのを思うと、先人への感謝の気持ちがわき上がりますね。

さて、勤労をねぎらうには温泉が一番です！
次回の花火では、温泉に浸かりながら楽しめるといいですね！

下呂温泉をよろしくお願いいたします！

下呂温泉観光協会HP
↓
https://www.gero-spa.com/topics/detail_326.html

#下呂温泉 #日本三名泉 #下呂市 #下呂観光 #下呂花火 #勤労感謝の日' where id = 'PupXxnfj6nAV13qVj333Z';
update content_bodies set title = 'Today''s Gero Onsen', description = 'On November 20th (Saturday), the "Tenjo Mukyu - Epidemic Extermination - Gero Onsen Fireworks Story" was held, themed "Labor Thanksgiving Fireworks".

This event was a prelude to Labor Thanksgiving Day on November 23rd (Tuesday), where we express gratitude for the labor and production that support our lives (3 and 9).

A grand display of fireworks was launched in celebration. It is said that this day originally stems from the Niiname-sai, a festival to give thanks for the bountiful harvest of grains.

There are various theories about how the gratitude for the harvest transformed into gratitude for labor, but thinking about how we can enjoy fireworks like this today fills me with appreciation for our predecessors.

Now, what better way to reward ourselves for our labor than with a hot spring!

I hope we can enjoy the next fireworks while soaking in the hot springs!

Thank you for your support of Gero Onsen!

Gero Onsen Tourism Association HP
↓
https://www.gero-spa.com/topics/detail_326.html

#GeroOnsen #JapanThreeFamousHotSprings #GeroCity #GeroTourism #GeroFireworks #LaborThanksgivingDay' where id = '7QEy4loEG-rbI6iFCCl3h';
update content_bodies set title = 'けふの下呂温泉', description = '１１月１２日（金）から、温泉寺で「温泉寺周辺ライトアップ」が開始されました。

見ごろを迎えた紅葉を、夜にも楽しむことができます。
お寺と紅葉の荘厳な景観は、心を落ち着かせてくれるようです。
写真を撮ったり、散策にいらしたお客様もみえ、静かで落ち着いた時間が流れています。

恒例の各種イベントのいくつかは、残念ながらコロナ感染予防のために中止となってしまいましたが、
『190歳の作品展‼』や『草木染のある暮らし展』といった催し物も開催しています。

ぜひ、ご覧にいらしてください。

紅葉ライトアップを楽しんだあとは、もちろん温泉へ浸かりましょう！
下呂温泉をよろしくお願いいたします！

