update content_bodies set title = 'Today’s Gero Onsen', description = 'From November 12 (Friday), the "Onsenji Surrounding Light Up" has started at Onsenji Temple.

You can enjoy the beautiful autumn leaves even at night.
The majestic scenery of the temple and the autumn leaves seems to calm the mind.
Visitors have come to take photos and stroll around, and a quiet, peaceful time is flowing.

Unfortunately, some of the regular events have been canceled due to COVID-19 prevention measures,
but events such as the "190-Year-Old Exhibition!!" and "Living with Natural Dyes Exhibition" are also being held.

Please come and see it.

After enjoying the autumn leaves light up, of course, let’s soak in the hot springs!
Thank you for your support of Gero Onsen!

