update content_bodies set title = 'けふの下呂温泉', description = '飛騨の山々をいろどる紅葉をイメージした、１１月６日（土）の「天壌無窮　悪疫退散　下呂温泉花火物語」の様子です。

寒さが日増しに強くなっている中でも、たくさんのお客様でにぎわっており、花火に歓声をあげていました。
紅葉の起源は奈良～平安時代にもさかのぼると言われているそうですが、
今も昔も多くの人々を楽しませてくれていますね。

夜風で冷えた体をあたためるには温泉がもってこい！
ちなみに、最初から全身をつかるよりも、半身浴から始めたほうがより効果的であるそうです。
下呂温泉をよろしくお願いいたします！

