update content_bodies set title = '#Amami #tabi 4K 10-minute version', description = 'A complete version of ''#Amami #tabi'' filled with the charm of Amami Oshima.

Amami Oshima, a UNESCO World Heritage recommended area, is rich in nature and unique culture.

''#Amami #tabi'' is a video where two women from Amami Oshima, who live away from the island, rediscover the charm of Amami Oshima while touring tourist spots and scenic locations by rental car.
Please use it as a reference before your trip to Amami Oshima.

And when you visit Amami Oshima, let''s share photos of the picturesque scenery that looks great on social media with the hashtag ''#Amami tabi''!

 #Amami tabi
 #Amami #tabi
 #Amami Oshima
 #Amami
 #AmamiOshima
 #Amamiisland' where id = 'M1pGm7pXswTghZiWmFnAP';
