update content_bodies set title = 'いのち、むきだし。奄美大島 　糸篇', description = 'https://amami-inochimukidashi.com/ 

奄美大島は2021年7月26日に世界自然遺産に登録されました。
全国に奄美大島の魅力を発信するとともに、世界自然遺産を後世に残すため、
消費収集型の観光ではないこれからの観光のカタチ「サスティナブル・ツーリズム」を
奄美大島が先頭に立って推進していかなければならないと考えています。

そこで、世界からの評価も高い奄美の生物多様性にスポットを当てながら、
旅行者の環境保全意識を高めていくことを目的とした
PRムービー「いのち、むきだし。奄美大島」を公開します。' where id = 'uBJllNvuGKwcPtZA-3we1';
update content_bodies set title = 'Life, Exposed. Amami Oshima - Thread Edition', description = 'https://amami-inochimukidashi.com/ 

Amami Oshima was registered as a UNESCO World Natural Heritage site on July 26, 2021. 
In addition to promoting the charm of Amami Oshima nationwide, we believe that it is essential for Amami Oshima to take the lead in promoting a new form of tourism, ''Sustainable Tourism,'' which is not based on consumption and collection, in order to preserve the World Natural Heritage for future generations. 

Therefore, while focusing on the high biodiversity of Amami, which is highly regarded worldwide, we are releasing a PR movie titled ''Life, Exposed. Amami Oshima'' aimed at raising travelers'' awareness of environmental conservation.' where id = 'oKw9igGs5q51Cpfp2ncI7';
update content_bodies set title = '城主クリス・ペプラーさんが語る、福知山城の魅力【明智光秀が築いた城下町 京都 福知山】', description = '＼　　　2020年大河ドラマ「麒麟がくる」放送直前！　　　／
　＼明智光秀の知られざる魅力と福知山城の盛り上がりを／
　　＼　　　　 クリス・ペプラーさんが発信 　　　　／

「明智光秀が築いた城下町 福知山」特別大使を務めるTV・ラジオ パーソナリティーのクリス・ペプラーさん主演、京都府福知山市のプロモーション動画です。

明智光秀の子孫とされるクリス・ペプラーさんは、2019年2月に福知山城で大使に就任。
3月にはPV「クリス・ペプラーさん 福知山城 新城主 就任記者会見」が公開され、今回はその続編となります。

【クリス・ペプラーさん コメント 】
前回の動画では『福知山市のさらなる発展に尽くす』と抱負を述べ、城主に就任しましたが、今回の動画では城主となった福知山城を自分のナレーションで伝えるものとなりました。お城を起点に福知山が盛り上がりつつあることが嬉しく、来年もこの盛り上がりが更なるものになるように、ぜひこの動画で更に福知山城と福知山に興味を持ってもらえたらと思います。

＊　＊　＊

本作は、福知山城を築いた明智光秀の知られざる魅力と福知山市とのつながりを全国に発信する「知られざる明智光秀プロジェクト」第5弾です！

「知られざる明智光秀プロジェクト」って・・・？という方は
こちらをご覧ください！
https://www.city.fukuchiyama.lg.jp/site/mitsuhide/

（福知山PR事業　自治体PR動画）' where id = 'O8_ncMyse1HkersfgVLzM';
update content_bodies set title = 'The Charm of Fukuchiyama Castle as Told by Lord Chris Peppler【The Castle Town Built by Akechi Mitsuhide, Kyoto Fukuchiyama】', description = '＼　　　Just before the broadcast of the 2020 Taiga drama "Kirin ga Kuru"!　　　／
＼ Discover the unknown charm of Akechi Mitsuhide and the excitement of Fukuchiyama Castle ／
　　＼　　　　 Presented by Chris Peppler 　　　　／

This is a promotional video for Fukuchiyama City, featuring TV and radio personality Chris Peppler, who serves as the special ambassador for "The Castle Town Built by Akechi Mitsuhide, Fukuchiyama."

Chris Peppler, believed to be a descendant of Akechi Mitsuhide, was appointed as an ambassador at Fukuchiyama Castle in February 2019. In March, the promotional video "Chris Peppler''s Press Conference for the New Lord of Fukuchiyama Castle" was released, and this is its sequel.

【Comment from Chris Peppler】
In the previous video, I expressed my ambition to "contribute to the further development of Fukuchiyama City" upon my appointment as lord, but in this video, I narrate the story of Fukuchiyama Castle as its new lord. I am delighted that Fukuchiyama is gaining momentum starting from the castle, and I hope this video will spark even more interest in Fukuchiyama Castle and Fukuchiyama next year.

＊　＊　＊

This work is the 5th installment of the "Unknown Akechi Mitsuhide Project," which aims to promote the unknown charm of Akechi Mitsuhide, who built Fukuchiyama Castle, and its connection to Fukuchiyama City nationwide!

What is the "Unknown Akechi Mitsuhide Project"...? If you''re curious, please check this out!
https://www.city.fukuchiyama.lg.jp/site/mitsuhide/

（Fukuchiyama PR Project Local Government PR Video）' where id = '4XUoHbxlricGjNa2Dl2-A';
update content_bodies set title = '鬼のいざない【京都府福知山市プロモーション動画】', description = '福知山市初のプロモーション動画『鬼のいざない』を公開中！
福知山を訪れた女性が鬼にいざなわれ、出会う“いがい”なものとは・・・？

（2018/3/31　再アップロードしました）
平成30年度京都広報賞　映像の部　知事賞受賞！！

戦国武将・明智光秀が築城したと伝わる福知山城や、おとぎ話でも知られる酒呑童子の伝説が残る大江山などを舞台に、「外から見た福知山の魅力」を表現した、ストーリー仕立ての映像となっています。４Ｋカメラやドローンを駆使し、福知山が一番美しい秋を美麗な映像と巧みなカメラワークで切り取りました。“いがい”なストーリー展開と、美麗な映像で送る４分間に福知山の魅力が詰め込まれています。ぜひ、最後まで御覧ください！

ロケーション解説はこちらから
