update content_bodies set title = 'さようなら寝台特急「出雲号」～フルバージョン～【１分１７秒】', description = '昭和４７年３月、山陰地方～東京間を山陰本線経由で結ぶ寝台特急としてデビューし、地元の東京方面への足として活躍してきた寝台特急「出雲号」。
