update content_bodies set title = 'Goodbye Sleeper Limited Express ''Izumo'' - Full Version - [1 minute 17 seconds]', description = 'In March 1972, the sleeper limited express ''Izumo'' debuted as a train connecting the San''in region to Tokyo via the San''in Main Line, serving as a vital link for locals traveling to Tokyo.
On March 18, 2006 (Saturday) at 7:25 AM, it passed through the Ayabe Bridge slightly late, as if to bid farewell. It departed while being seen off by many fans.' where id = 'x0v-FfdeylNO47nQKtCW3';
update content_bodies set title = 'さようなら寝台特急「出雲号」【３５秒】', description = '昭和４７年３月、山陰地方～東京間を山陰本線経由で結ぶ寝台特急としてデビューし、地元の東京方面への足として活躍してきた寝台特急「出雲号」。
