update content_bodies set title = 'Goodbye Sleeper Limited Express ''Izumo'' [35 seconds]', description = 'In March 1972, the sleeper limited express ''Izumo'' debuted as a train connecting the San''in region to Tokyo via the San''in Main Line, serving as a vital link for locals traveling to Tokyo.
