https;//kami-tabi.jp/' where id = 'VmEPpHuQzEY9GE3bcg2Lz';
update content_bodies set title = 'Kaminaka Town Drone PR Video (Sea Edition)', description = 'The San''in Kaigan Geopark is composed of six cities and towns facing the Sea of Japan, including Kyotango City in Kyoto Prefecture, Toyooka City and Shinonsen Town in Hyogo Prefecture, Kaminaka Town, and Tottori City and Iwami Town in Tottori Prefecture. It has been designated as a UNESCO Global Geopark due to the beauty and geological significance of its landscape.

Enjoy the beautiful nature of Kaminaka Town through this PR video.

---
If you want to enjoy Kaminaka Town even more, we recommend the official tourism app ''kami-tabi''!
https://kami-tabi.jp/' where id = '_w1RroqvjeDDPexLayofQ';
