update content_bodies set title = 'A Journey to Satisfy the Five Senses: Kami Town - Nature''s Colorful ''Taste''', description = 'We have created a promotional video for tourism based on the concept of ''A Journey to Satisfy the Five Senses: Kami Town.''
Please enjoy Kami Town through the elements of view (眺), sound (響), fragrance (香), taste (味), and healing (癒).
This video features the element of ''Taste'' (味) and is 60 seconds long.

The filming locations featured in this video are as follows:
Kasumi Fishing Port - Selection of Matsuba Crab
Matsuba Crab
Muraoka Rice
Kasumi Crane
Komeji Miso
Kasumi Pear
Tajima Beef Barn and Steak Meat

