update content_bodies set title = 'A Journey to Satisfy the Five Senses: Kami Town - 90 Seconds Full Version', description = 'Congratulations! Selected for the Official Selection in the Japan Category at the 4th Japan International Tourism Film Festival (2022)

This is a tourism PR video created with the concept of "A Journey to Satisfy the Five Senses: Kami Town." 
Please enjoy Kami Town through the elements of view (nagame), sound (hibiki), scent (kaori), taste (aji), and healing (iyashi).
This video features the full version (90 seconds) of each of the five senses.

The filming locations featured in this video are as follows:
