update content_bodies set title = '#飛騨高山 の桜　cherry blossoms', description = '岐阜県高山市は、雄大な山々に囲まれた自然豊かなエリア。日本一面積が広く、桜の開花時期が異なり長く桜の美しい風景が楽しめます。

観光名所の赤い中橋と桜のコントラスト、山間の隠れた名所で楽しむ幻想的な花景色。高山の桜は、訪れる人々の心を癒やし、特別な旅の思い出を演出してくれます。ぜひ、春の息吹を感じながら桜巡りを楽しんでみませんか？

Dp. Ed. Cam.：Motohiko Hino

