update content_bodies set title = '#Hida Takayama''s Cherry Blossoms', description = 'Takayama City in Gifu Prefecture is a nature-rich area surrounded by majestic mountains. It has the largest area in Japan, where the cherry blossom blooming period varies, allowing for a long enjoyment of beautiful cherry blossom scenery.

The contrast between the red Nakabashi Bridge, a tourist attraction, and the cherry blossoms creates a fantastic floral landscape in hidden spots in the mountains. The cherry blossoms of Takayama heal the hearts of visitors and create special travel memories. Why not enjoy a cherry blossom tour while feeling the breath of spring?

Dp. Ed. Cam.: Motohiko Hino

