update content_bodies set title = '#Hida Takayama Flower Tour', description = 'Takayama City in Gifu Prefecture is a nature-rich place where beautiful flowers bloom throughout the four seasons. In spring, pale pink cherry blossoms envelop the town, in summer, delicate water buttercups sway in the clear streams, and in autumn, wildflowers add color alongside the autumn leaves. The Fukujusō, which blooms around the time of snowmelt, heralds the early arrival of spring with its golden glow.
Experience the beautiful harmony of flowers and landscapes woven by Takayama''s rich nature. Why not take a leisurely stroll while enjoying the changing expressions of flowers with each season?' where id = 'HO6QFZWPzEKKog1_mDiw6';
update content_bodies set title = '#飛騨高山　FarmersGifts Hidarice', description = '飛騨高山のお米 — 自然の恵みが育む極上の味わい
岐阜県高山市は、澄んだ空気と清らかな水、昼夜の温度差が豊かな環境です。飛騨山脈に囲まれたこの地で、手間ひまかけて栽培されるお米は、甘みが際立ち、ふっくらとした食感が特徴。豊かな自然に囲まれた高山市の大地が育むお米は、一粒一粒に深い旨味が詰まっています。

Drone Camera Operator： Hiroyuki Tanbo
Dp. Ed. Cam.：Motohiko Hino

