update content_bodies set title = '#飛騨高山　FarmersGifts megumi', description = '岐阜県高山市は、日本の美しい自然が広がる魅力的な地域です。山々に囲まれ、清らかな水と肥沃な土地に恵まれ、四季折々の豊かな恵みをもたらします。寒暖差のある環境の中で育つ野菜や果物は、栄養価が高く、甘みや美味しさが詰まっており、食感も抜群！

自然との調和を大切にした農法が採用され、安心して口にできる食材が揃っています。直売所や市場で旬の食材を直接購入でき、地元ならではの味を楽しむことができます。

大自然の息吹を感じながら、地元の豊かな味覚を堪能できる高山は、健康志向の方にもおすすめのエリアです。四季折々の風景とともに、心も体も満たされるひとときをお過ごしください。

Dp. Ed. Cam.：Motohiko Hino

