update content_bodies set title = '#飛騨高山 自然と歴史が調和する町　#一之宮', description = '自然の恵みと山里の食、臥龍桜やどぶろくを堪能
田舎暮らしと、地元の人たちとのふれあいが体験できる「グリーンツーリズム」が盛んな一之宮町。町のシンボルである臥龍桜を眺め、分水嶺が見られる位山の散策を楽しむなど、自然の恵みと山里の食を体感できます。内閣府認定の「どぶろく特区」で、町内の民宿やレストランでこの町で作られたどぶろくが味わえるのも嬉しいポイント。また、冬季にはモンデウスパークで白銀のゲレンデが広がるウィンタースポーツの舞台が広がります。

