update content_bodies set title = '#Hida Takayama - A Town Where Nature and History Harmonize #Ichinomiya', description = 'Experience the blessings of nature and the local mountain cuisine, including Goryo cherry blossoms and doburoku.

Ichinomiya Town is active in ''Green Tourism,'' where you can experience rural living and interact with local people. You can enjoy the view of the town''s symbol, the Goryo cherry blossoms, and take a stroll on Mt. Wiyama, where you can see the watershed, experiencing the blessings of nature and the local mountain cuisine. It''s also a delight that you can taste doburoku made in this town at local inns and restaurants in the ''Doburoku Special Zone'' certified by the Cabinet Office. Additionally, during the winter season, the Mondeu Park offers a winter sports venue with a silver-white ski slope.

