update content_bodies set title = '御岳山と乗鞍岳を望む #飛騨高山 「高根町」', description = '明治から大正時代、貧しい飛騨から遠く信州へと糸引き稼ぎに行く娘たちが通った野麦街道を擁する「飛騨高根」。御岳山の北端、継子岳と乗鞍岳を望む、自然豊かなエリアです。大自然を生かしたキャンプ場も多く、秋には美しい紅葉が楽しめます。
夏でも涼しい高地の環境を生かし、アスリートたちがトレーニングに訪れる地として注目されています。また、その気候を活かして栽培される在来の品種「火畑そば」も人気！ぜひ、飛騨高根を訪れてみてはいかがでしょうか。


