update content_bodies set title = 'Mt. Ontake and Mt. Norikura View #Hida Takayama ''Takane Town''', description = 'In the Meiji to Taisho era, ''Hida Takane'' was a place where poor girls from Hida traveled far to Shinshu to earn a living along the Nomugi Highway. It is a nature-rich area that offers views of Mt. Ontake''s northern edge, Mt. Kegusuko, and Mt. Norikura. There are many campsites that take advantage of the great outdoors, and in autumn, you can enjoy beautiful autumn leaves.
Taking advantage of the cool highland environment even in summer, it has gained attention as a place where athletes come to train. Additionally, the indigenous variety ''Hibata Soba'' cultivated in this climate is also popular! Why not visit Hida Takane?' where id = 'CNBkNhxispzhp3ziJu7at';
update content_bodies set title = '秘境と神話が眠る町　#丹生川', description = '北アルプスの南端・乗鞍岳に抱かれる丹生川町。ライチョウが棲む乗鞍岳は、山岳の世界を気軽に体感させてくれます。その麓、五色が原には原生林が広がり、秘境の森が守られています。丹生川町は、トマトやホウレンソウの生産が盛んで、北アルプスから生まれる水で育った野菜はどれも滋味に溢れています。また、サイクリストが訪れる地でもあり、農山村の風景と乗鞍岳の絶景が魅了し、ペダルをこぐ脚には活力を与えます。四季の移ろいを魅せる農山村の風景はどこか懐かしく未来へと残したい宝物です。

