update content_bodies set title = 'A Town Where Hidden Realms and Myths Sleep #Niu River', description = 'Niu River Town, nestled at the southern end of the Northern Alps, Mount Norikura. 
Mount Norikura, home to the Japanese rock ptarmigan, allows you to easily experience the world of mountains. 
At its foot, the Goshikigahara area is covered with primeval forests, protecting a hidden realm of woods. 
Niu River Town is known for its active production of tomatoes and spinach, and the vegetables grown with water from the Northern Alps are all rich in flavor. 
It is also a destination for cyclists, where the picturesque rural landscape and the breathtaking views of Mount Norikura captivate, energizing the legs that pedal. 
The changing scenery of the rural landscape through the seasons is a nostalgic treasure that we want to preserve for the future.' where id = 'qwxyvk4rpjS69rh2U8KQp';
update content_bodies set title = '城下町の面影薫る歴史と文化を凝縮した町　#飛騨高山', description = '城下町としての面影が色濃く残る高山市街地。江戸時代の風情が漂う古い町並や、国内に唯一現存する徳川幕府の遺構・高山陣屋、日下部民芸館など、高山市街には歴史を重ねた建物が数多く残されています。また、城下町を築き、高山城を拠点に藩政を行った武将・金森長近ゆかりの地を巡り、想いを馳せるのも趣があります。

