update content_bodies set title = 'A Town Condensed with History and Culture of the Castle Town #HidaTakayama', description = 'The city of Takayama retains a strong resemblance to its past as a castle town. The old streets exude the atmosphere of the Edo period, and numerous historical buildings remain in the city, including the Takayama Jinya, the only existing structure from the Tokugawa shogunate in Japan, and the Kusakabe Folk Museum. Additionally, exploring the sites associated with the samurai Kanamori Nagachika, who established the castle town and governed the domain from Takayama Castle, adds to the charm.' where id = 'lrIj-gSY5RVL1eoSYRhxK';
