update content_bodies set title = '#飛騨高山 　秋の #高山祭　2022年10月9日、10日', description = '秋の高山祭（八幡祭）は櫻山八幡宮の例祭で毎年10月9日・10日に開催されます。2022年はあいにくの雨模様で、御神幸や宵祭は中止になりましたが、からくり奉納など無事に開催されました。
豪華絢爛な屋台、精巧な動きが魅力的なからくり人形など、高山祭の様子を短くまとめました。ぜひ、ご覧ください。

