update content_bodies set title = '#Hida Takayama Autumn #Takayama Festival October 9th and 10th, 2022', description = 'The Autumn Takayama Festival (Hachiman Festival) is a festival held annually on October 9th and 10th at Sakurayama Hachiman Shrine. Unfortunately, in 2022, due to rainy weather, the procession and evening festival were canceled, but the karakuri performances were successfully held. This is a brief summary of the Takayama Festival, featuring the luxurious floats and the intricately moving karakuri dolls. Please take a look.

