update content_bodies set title = 'この旅 多彩 濃色 飛騨高山 観光ムービー', description = '日本一面積が広い市である高山市は、町のすみずみまでたくさんの見どころに溢れています。城下町の雰囲気が色濃く残る古い町並はもちろん、歴史や文化をはじめ知られざる逸話や日常では味わえない体験など多彩な魅力が満載。
旅を、思い出を、もっと色濃く、鮮やかに。
私たちの町、飛騨高山へようこそ。

