update content_bodies set title = 'This Journey: A Colorful and Vivid Takayama Tourism Movie', description = 'Takayama City, the largest city in Japan by area, is filled with numerous attractions throughout the town. The old streets, where the atmosphere of a castle town remains strong, are just the beginning. The city is rich in history and culture, with unknown anecdotes and experiences that cannot be enjoyed in everyday life, offering a diverse array of charms.
Make your journey and memories more vivid and colorful.
Welcome to our town, Hida Takayama.

