update content_bodies set title = '2022年春の#高山祭　山王祭', description = '春の高山祭(山王祭)は旧高山城下町南半分の氏神様である日枝神社の例祭で毎年4月14日、15日に開催されます。祭りの起源は飛騨の領国大名金森氏の時代、屋台の起こりは1718年頃といわれ、巧みな人形の動きを披露するからくり奉納や、仕掛けが施された戻し車など、匠の技が生きています。
2022年の春の高山祭はあいにくの雨模様でしたが、雨が止んだ合間に屋台が蔵から出て古い町並を通る様子が見られました。

#飛騨高山　#高山　#hidatakayama　#takayama  #高山祭 #山王祭
