update content_bodies set title = '2022 Spring Takayama Festival - Sanno Festival', description = 'The Spring Takayama Festival (Sanno Festival) is the annual festival of Hie Shrine, the guardian deity of the southern half of the old Takayama castle town, held on April 14 and 15 each year. The origins of the festival date back to the time of the Hida feudal lord Kanamori, and the beginnings of the floats are said to be around 1718. The festival showcases the skillful movements of karakuri puppets and features mechanisms such as the returning wheel, highlighting the craftsmanship of artisans.
The 2022 Spring Takayama Festival unfortunately experienced rainy weather, but during breaks in the rain, the floats could be seen coming out of the storehouses and passing through the old town streets.

