update content_bodies set title = '#Hida Takayama Autumn Leaves', description = 'Hida Takayama, surrounded by the majestic nature represented by the Hida Mountains (Northern Alps). Takayama City, the largest city in Japan, begins to see autumn leaves around late October, in accordance with the elevation differences. Here are some autumn leaf spots in Hida Takayama.' where id = 'PyKwGxU1jL-e5FwizUy8l';
update content_bodies set title = '#飛騨高山 手筒花火打ち上げ (#手筒花火)', description = '飛騨高山の夏の風物詩！毎年8月9日に開催される「飛騨高山手筒花火打ち上げ」。宮川の川床に仮設台を設け、飛騨高山手筒組の面々が竹筒に仕込んだ花火を手で持ち、火の粉をあびながら行う勇壮な花火です。打ち上げの終わりに轟く爆音、豪快に噴き上がる火柱は迫力満点！打ち上げる者、観る者の厄払いを願い、毎年8（や）月9（く）日に開催されています。


