update content_bodies set title = '#Hida Takayama Handheld Fireworks Display (#HandheldFireworks)', description = 'A summer tradition in Hida Takayama! The ''Hida Takayama Handheld Fireworks Display'' is held every year on August 9th. A temporary platform is set up on the banks of the Miyagawa River, where members of the Hida Takayama Handheld Fireworks Group hold bamboo tubes filled with fireworks, creating a magnificent display while being showered with sparks. The thunderous sound at the end of the display and the towering flames are truly impressive! It is held every year on August 9th to wish for the purification of both the participants and the spectators.' where id = '4J1GcEGakPuUZe3BgjrMK';
update content_bodies set title = '#飛騨高山 の滝', description = '飛騨山脈(北アルプス）をはじめ、雄大な自然に囲まれ、江戸時代の面影を残す古い町並や、高山祭など歴史と伝統文化が息づく町「飛騨高山」。日本一面積が広い市である高山市には、迫力満点な平湯大滝をはじめ、岐阜県名水５０選地や日本の自然100選にも選ばれている滝を見ることができます。

