update content_bodies set title = '#Hida Takayama Waterfalls', description = 'Surrounded by the majestic nature of the Hida Mountains (Northern Alps), the town of Hida Takayama retains the charm of the Edo period with its old streets and is alive with history and traditional culture, such as the Takayama Festival. In Takayama City, which has the largest area of any city in Japan, you can see impressive waterfalls, including the powerful Hirayu Great Falls, as well as selected sites from Gifu Prefecture''s 50 Famous Waters and Japan''s 100 Natural Wonders.' where id = 'R_Va_a9eIUWtoTPF46KpG';
