update content_bodies set title = '長岡市ふるさとCM「最高のいっぱいに出会えるまち」（30秒版）（令和4年制作／第3回新潟ふるさとCM大賞 出品作品）', description = '長岡は、最高のいっぱいに出会えるまちです。長岡ならではの生姜醤油ラーメン、山盛りの枝豆、寺泊の海でとれる大漁のサザエ、ものづくりの技術を活かしたアルミ鋳物のぐい呑み、花火を見ながらの一杯など...。作られるまでの物語や情熱とともに魅力を味わってください。
　　　　　　　
「第3回新潟ふるさとCM大賞」第4位を受賞！
県内27市町村がふるさと自慢のCMを制作・出品。令和4年11月10日（木）の審査会で第4位を受賞しました。
詳しくはUX新潟テレビ２１のサイトをご覧ください。
