update content_bodies set title = 'Nagaoka City Hometown CM ''A Town Where You Can Meet the Best of Everything'' (30-second version) (Produced in 2022 / Entry for the 3rd Niigata Hometown CM Awards)', description = 'Nagaoka is a town where you can meet the best of everything. Enjoy the unique ginger soy sauce ramen, heaping servings of edamame, the abundant sea urchins caught in Teradomari, aluminum cast sake cups made with craftsmanship, and a drink while watching fireworks... Experience the charm along with the stories and passion behind their creation.

Awarded 4th place in the ''3rd Niigata Hometown CM Awards''! 
27 cities and towns in the prefecture produced and submitted their hometown pride CM. We received 4th place at the judging session on November 10, 2022 (Thursday). 
For more details, please visit the UX Niigata TV 21 website. 
https://www.uxtv.jp/furusato_cm/

