update content_bodies set title = '長岡市ふるさとCM「最高のいっぱいに出会えるまち」（3分版）（令和4年制作）', description = '長岡は、最高のいっぱいに出会えるまちです。長岡ならではの生姜醤油ラーメン、山盛りの枝豆、寺泊の海でとれる大漁のサザエ、ものづくりの技術を活かしたアルミ鋳物のぐい呑み、花火を見ながらの一杯など...。作られるまでの物語や情熱とともに魅力を味わってください。

