update content_bodies set title = 'Nagaoka City Hometown CM ''A Town Where You Can Meet the Best of Everything'' (3-Minute Version) (Produced in 2022)', description = 'Nagaoka is a town where you can meet the best of everything. Enjoy unique local delicacies such as ginger soy sauce ramen, heaping servings of edamame, the abundant catch of turban shells from Teradomari''s sea, aluminum cast sake cups made with craftsmanship, and a drink while watching fireworks... Experience the charm along with the stories and passion behind their creation.

