update content_bodies set title = '長岡市ふるさとCM「長岡花火の想いを未来へ」（令和2年制作／第1回新潟ふるさとCM大賞 出品作）', description = '長岡花火に込められた慰霊・復興・平和への想いは、花火大会が中止になった今年も尺玉の打ち上げや「道の駅 ながおか花火館」の開館があり、途絶えることなく未来へとつながっています。' where id = 'bgiRqsm_lfkZ3JDq8vUGQ';
update content_bodies set title = 'Nagaoka City Hometown CM ''The Feelings of Nagaoka Fireworks for the Future'' (Produced in 2020 / Entry for the 1st Niigata Hometown CM Award)', description = 'The feelings of memorial, reconstruction, and peace embedded in the Nagaoka Fireworks continue to connect to the future without interruption, even this year when the fireworks festival was canceled, with the launch of large fireworks and the opening of the ''Roadside Station Nagaoka Fireworks Museum.''' where id = 'WiFiQ94f4YsKo9gvxKxyr';
