update content_bodies set title = '「寺泊」観光PR動画　～歴史薫るつわぶきのまち～', description = '「北の鎌倉」と称される寺泊。有名な魚の市場通り（魚のアメ横）から少し歩けば、由緒ある史跡や神社仏閣が集まる「寺泊歴史街道（ロマンス街道）」があります。
秋には、凛とした黄色い花「つわぶき」が至る所で咲き、街並みに彩を添えます。

海や魚だけじゃない、「歴史薫るつわぶきのまち・寺泊」をぜひ散策してみてください。

