update content_bodies set title = 'Teradomari Tourism PR Video - A Town of Tsuwabuki with a Rich History', description = 'Teradomari, known as the ''Kamakura of the North.'' Just a short walk from the famous Fish Market Street (Uo no Ameyoko), you will find the ''Teradomari Historical Street (Romance Road)'' where historic sites and shrines are gathered.
In autumn, the striking yellow flower ''tsuwabuki'' blooms everywhere, adding color to the townscape.

Not just the sea and fish, but please take a stroll through ''Teradomari, a Town of Tsuwabuki with a Rich History.''

