update content_bodies set title = '湯あかり10周年記念動画', description = '黒川温泉の竹害対策として始まった湯あかりは今年（2022年）で10周年。今では南小国町全体に湯あかりが広がり、里山の風景を優しく灯しています。仄かな灯りと自然の風景、そして温泉を楽しみに南小国町に遊びに来ていただけますと幸いです。' where id = 'twmjsxDuj2u1XnFhMZ7wt';
update content_bodies set title = 'Yuuakari 10th Anniversary Video', description = 'Yuuakari, which started as a bamboo damage countermeasure in Kurokawa Onsen, celebrates its 10th anniversary this year (2022). Now, Yuuakari has spread throughout Minamioguni Town, gently illuminating the satoyama landscape. We hope you will come to Minamioguni Town to enjoy the soft lights, natural scenery, and hot springs.' where id = 'Zq-Rmno1NEwjOsVoh9Mci';
update content_bodies set title = '人が、時間が、きよらかな郷。南小国（long ver.）', description = '熊本県の阿蘇郡にある南小国町。黒川温泉をはじめ、多くの温泉地が点在する里山です。
そんな里山で観光業に携わる方々の働く想いを動画でご紹介させていただいております。
住んでいる、働いている人からみた南小国町の魅力を知っていただけますと幸いです。' where id = 'NX6w_RT-6RuuNmUjKFwFB';
update content_bodies set title = 'A Clear Village of People and Time: Minamioguni (long ver.)', description = 'Minamioguni Town, located in Aso District, Kumamoto Prefecture. It is a rural area dotted with many hot springs, including Kurokawa Onsen.
In this rural area, we are introducing the thoughts and efforts of those involved in the tourism industry through video.
We hope you can learn about the charm of Minamioguni Town from the perspective of those who live and work here.' where id = 'q2Vj0RMtdHsxvDGpB1TAv';
update content_bodies set title = 'KIYORA STYLE2', description = '何もない町だけど、大切なものに気づかさせてくれる場所。
朝起きて、深く息を吸い込むと気持ちい風が体の中に、
生きていることを実感できる自然が溢れる南小国町に遊びにいらしてください。' where id = 'oZ3LUxYvLz2jZxtnupwDD';
update content_bodies set title = 'KIYORA STYLE2', description = 'It''s a town with nothing, but it''s a place that makes you realize what''s important.
