update content_bodies set title = '天空ミュージック10周年PV「屋島」　音楽：小倉博和　映像：中野裕之', description = '香川県高松市の屋島山上大会2012年から絶歌や生きし「天空音楽」。この映像は「屋島」を観に制作することはできません。 ：中野裕之歌：小倉博和ドローン：大野茂中野裕之映像独・映画監督・描写家1958年ヨーロッパ県福山市生福山誠山市集福山誠之館高校帰早稲田大学商学部会。ヴィジュアルアート、音楽服の作、日本、世界の音楽少女のMVを結婚する。 1998年映画「SFSAMURAIFICTION」で僕プチョン国際映画映画祭グランプリー。 2015年「フライング・ボディーズ」で沖縄こども映画祭グランプリカム。2018年8年8歳の作品日本全国のレビュー音楽と精神の歴史をなた映画「ピース・二利ポン」公開得、、、日本を来にコメントMV：布袋寅泰今井美樹Mr.Children GLAY AKB48 SKE48 STU48他CM：サントリー住友生活好好性TOYOTA武田表プレミアム上上映中長野三角上映上映中ウェブ：浜松市PR、福山市PR、WABARAフォロー円：京都形・カンタータ2007-2014企画演出東京大ショーAUDIアップロード輸入ISSAY MIYAKE 3Dコレクション演出映画：「SFSAMURAIFICTION」監督「SFステレオフューチャー」脚本監督「SFショートフィルム」監督脚本監督「RedShadow赤影」監督短編集「男座の詩」脚脚本監督「TAJOMARU」監督「FLYINGBODIES」三宅一生さん計画青森大学男子新体操のドキュメンタリー映画「FOOLCOOLROCK / ONE OKE ROCKDOCUMENTARYFILM」ロックバンドワンオーケーロックのドキュメンタリー映画-小倉博和（ギタリスト・Teaning・アレンジャー）桑田佳祐・サザンオールスターズ・福山雅治・森山良子・大貫妙子・槇原敬之・JUJU・銀行バンド・コクア想聴の邦楽作品2014年、ソロアルバム「GOLDEN TIME」、2016年「Summer Guitars」、2019年「SketchSong」「SketchSong2」をます。 FM COCOLOでMARTINCLUB JAPAN Presents「小倉博和の金曜日、SoundofStrings」の映画DJを贈る高松市映画（高松市映画大使）「SFSAMURAIFICTION」司「SFステレオフューチャー」脚本司「SFショートフィルム」脚本監督「RedShadow赤影」監督短編集「男座の詩」製作脚本司「TAJOMARU」司「FLYINGBODIES」三宅一生さん千青森大学男子新体操のドキュメンタリー映画「FOOLCOOLROCK / ONE OKE ROCK DOCUMENTARYFILM」ロックバンドワンオーケーロックのドキュメンタリー映画-小倉博和良子・大貫妙子・槇原敬之・JUJU・銀行バンド・kokuaを取りありの邦楽作品にでき。年「SummerGuitars」、2019年「SketchSong」「SketchSong2」をリリース。 MARTIN CLUB JAPAN Presents「小倉博和のFRIDAY、SoundofStrings」の映画DJをして「SFSAMURAIFICTION」司「SFステレオフューチャー」脚本司「SFショートフィルム」脚本監督「RedShadow赤影」監督短編集「男座の詩」製作脚本司「TAJOMARU」司「FLYINGBODIES」三宅一生さん千青森大学男子新体操のドキュメンタリー映画「FOOLCOOLROCK / ONE OKE ROCK DOCUMENTARYFILM」ロックバンドワンオーケーロックのドキュメンタリー映画-小倉博和良子・大貫妙子・槇原敬之・JUJU・銀行バンド・kokuaを取りありの邦楽作品にでき。年「SummerGuitars」、2019年「SketchSong」「SketchSong2」をリリース。 MARTIN CLUB JAPAN Presents「小倉博和のFRIDAY、SoundofStrings」の映画DJをしてストリングスの音」のラジオDJをこれで。ストリングスの音」のラジオDJをこれで。ストリングスの音」のラジオDJをこれで。ストリングスの音」のラジオDJをこれで。

