update content_bodies set title = 'Tenku Music 10th Anniversary PV ''Yashima'' Music: Hirokazu Ogura Video: Hiroyuki Nakano', description = 'The Yashima Mountain Summit Festival in Takamatsu City, Kagawa Prefecture, has been singing ''Tenku Music'' since 2012. This video cannot be produced to watch ''Yashima''.: Hiroyuki Nakano Song: Hirokazu Ogura Drone: Shigeru Ohno Hiroyuki Nakano Video Independent Film Director and Depictor Born in 1958 in Fukuyama City, Hiroshima Prefecture, graduated from Fukuyama Seishi High School and Waseda University Faculty of Commerce. Creating visual art and music clothing, marrying music videos of girls from Japan and around the world. In 1998, won the Grand Prix at the Puchon International Fantastic Film Festival with the film ''SFSAMURAIFICTION''. In 2015, won the Grand Prix at the Okinawa Children''s Film Festival with ''Flying Bodies''. In 2018, released the film ''Peace: Nari Pon'', which reviews the history of music and spirit across Japan. Comments on music videos: Tomoyasu Hotei, Miki Imai, Mr.Children, GLAY, AKB48, SKE48, STU48, etc. CM: Suntory, Sumitomo Life, Toyota, Takeda Premium currently screening in Nagano Triangle. Web: Hamamatsu City PR, Fukuyama City PR, WABARA Follow Circle: Kyoto Form & Cantata 2007-2014 Planning and Direction Tokyo Grand Show AUDI Upload Import ISSAY MIYAKE 3D Collection Direction Film: ''SFSAMURAIFICTION'' Director ''SF Stereo Future'' Screenplay Director ''SF Short Film'' Director Screenplay Director ''Red Shadow Akakage'' Director Short Story Collection ''Men''s Poem'' Screenplay Director ''TAJOMARU'' Director ''FLYING BODIES'' Issey Miyake''s plan Aomori University Men''s Rhythmic Gymnastics Documentary Film ''FOOL COOL ROCK / ONE OK ROCK DOCUMENTARY FILM'' Documentary film of the rock band One OK Rock - Hirokazu Ogura (Guitarist, Teaning, Arranger) Keisuke Kuwata, Southern All Stars, Masaharu Fukuyama, Ryoko Moriyama, Taeko Onuki, Noriyuki Makihara, JUJU, Bank Band, Kokua''s works of Japanese music. In 2014, released solo albums ''GOLDEN TIME'', ''Summer Guitars'' in 2016, and ''Sketch Song'' and ''Sketch Song 2'' in 2019. FM COCOLO presents MARTIN CLUB JAPAN ''Hirokazu Ogura''s Friday, Sound of Strings'' as a film DJ, Takamatsu City Film (Takamatsu City Film Ambassador) ''SFSAMURAIFICTION'' Director ''SF Stereo Future'' Screenplay Director ''SF Short Film'' Screenplay Director ''Red Shadow Akakage'' Director Short Story Collection ''Men''s Poem'' Production Screenplay Director ''TAJOMARU'' Director ''FLYING BODIES'' Issey Miyake''s plan Aomori University Men''s Rhythmic Gymnastics Documentary Film ''FOOL COOL ROCK / ONE OK ROCK DOCUMENTARY FILM'' Documentary film of the rock band One OK Rock - Hirokazu Ogura Ryoko Moriyama, Taeko Onuki, Noriyuki Makihara, JUJU, Bank Band, Kokua''s works of Japanese music. In 2014, released solo albums ''Summer Guitars'', ''Sketch Song'' and ''Sketch Song 2'' in 2019. MARTIN CLUB JAPAN presents ''Hirokazu Ogura''s FRIDAY, Sound of Strings'' as a film DJ and radio DJ of ''Sound of Strings''.' where id = 'OsJEmG9tp5p8MB8QH9kCC';
