update content_bodies set title = 'toRmansionより11月26，27日　サンポート高松第2小ホールの高松初演音楽劇「青い鳥と赤い猫　～～奇妙な旅の果てのはて？～へのメッセージ動画が届きました！！', description = '高松をイメージして創作された「チャラン・ポ・ランタン＆toRmansion」の完全新作音楽劇
「青い鳥と赤い猫」～奇妙な旅の果てのはて？～」
11月26（金），27日（土）サンポートホール高松第小ホール公演に向けて
今大人気のtoRmansionのメンバーからたった今、メッセージ映像が届きました。
