toRmansion プロフィール
2007年結成。現在までに16カ国82都市の劇場や演劇祭、ストリートフェスティバルから招聘され、世界中で大人気のパフォーマンスカンパニー。フランスのアビニョン演劇祭では1082演目中の口コミトップ20に選ばれ、連日ソールドアウトとなる。神戸ビエンナーレ大道芸コンペティションでグランプリを２度獲得するなど受賞歴多数。フランスの有力紙リベラシオン紙でも「日本から来た凄まじいこの劇団は、スラップスティックコメディを上演し、夜は広場の群衆を笑いに包む。」と紹介されるなど、海外でも高く評価されている。かのファッションデザイナー、ジャンポール・ゴルチエ氏も彼らの大ファンである。
