update content_bodies set title = 'Message video has arrived for the Takamatsu premiere musical "The Blue Bird and the Red Cat - A Message from the End of a Strange Journey?" at Sunport Takamatsu Small Hall on November 26 and 27 from toRmansion!!', description = '"The Blue Bird and the Red Cat - A Message from the End of a Strange Journey?" is a completely new musical created with the image of Takamatsu in mind by "Charan-Po-Rantan & toRmansion". 
