Stay tuned!! 
toRmansion Profile 
Founded in 2007. Invited to theaters, theater festivals, and street festivals in 82 cities across 16 countries, they are a globally popular performance company. At the Avignon Theatre Festival in France, they were selected as one of the top 20 in word-of-mouth out of 1082 performances, selling out every day. They have won the Grand Prix twice at the Kobe Biennale Street Performance Competition, among many other awards. The influential French newspaper Libération introduced them as "This incredible theater company from Japan performs slapstick comedy and fills the crowds in the square with laughter at night," receiving high praise overseas. The famous fashion designer Jean-Paul Gaultier is also a big fan of theirs. 
