update content_bodies set title = 'チャラン・ポ・ランタン＆toRmansion「青い鳥と赤い猫～奇妙な旅の果てのはて？〜」', description = '文化庁ARTS for the future!事業　今年夏から延期となり先日11月26，27日にサンポートホール高松第２小ホールで行われた高松初演の音楽劇のドキュメント！「チャラン・ポ・ランタン」「toRmansion」「せせらぎ」という出演者が強力なエンターテイメントスピリッツでつづるタペストリーは観る人の心にハートフルな希望の光を投げかけます！ご覧ください。' where id = '_J8kLSfFrf5Ye3qpMYw74';
update content_bodies set title = 'Charan-Po-Rantan & toRmansion ''The Blue Bird and the Red Cat - At the End of a Strange Journey?''', description = 'The Cultural Affairs Agency''s ARTS for the future! project. This is a documentary of the musical that was postponed from this summer and recently held its Takamatsu premiere on November 26 and 27 at the Sunport Hall Takamatsu, Small Hall 2! The tapestry woven by the performers ''Charan-Po-Rantan'', ''toRmansion'', and ''Seseragi'' casts a heartwarming light of hope into the hearts of those who watch it! Please take a look.' where id = 'QmhB-tkkdmGsC-AwKRDBZ';
