update content_bodies set title = 'TAKAMATSU MUSIC BLUE FES2024', description = '高松ミュージックブルーフェス 2024
2024年5月4日（土）5日（日）

「FLY WITH YOUR WIND」～自由に空を舞おう、君の風に乗って～

毎年GWに行われている「高松ミュージックブルーフェス」。
当フェスは街角から様々な音楽があふれ、人々がコミュニティや年齢を超えて文化に出会い、楽しんでいただく風景を創出する「まちなかパフォーマンス事業」として開催しています。

「音楽のマザーポート」
今回はHPにて応募したところおかげさまで東京や愛知など県内外からも多くのミュージシャンの応募があり高松で多くの音楽の交流が生まれます。

