update content_bodies set title = 'TAKAMATSU MUSIC BLUE FES2024', description = 'Takamatsu Music Blue Fest 2024
May 4th (Saturday) and 5th (Sunday)

"FLY WITH YOUR WIND" ~ Let''s dance freely in the sky, riding on your wind ~

The "Takamatsu Music Blue Fest" is held every year during Golden Week.
This festival is organized as a "city performance project" that creates a scene where various music overflows from street corners, allowing people to encounter and enjoy culture beyond community and age.

"Mother Port of Music"
This time, thanks to applications submitted through our website, we have received many applications from musicians both inside and outside the prefecture, including Tokyo and Aichi, leading to a rich exchange of music in Takamatsu.

87 general participants, 4 guest groups, a total of 91 groups (25 groups from outside the prefecture)

→ May 5th, Sunport Takamatsu Multipurpose Square
