update content_bodies set title = '【週末ルーティーン】手間を惜しむのではなく、手間を楽しむ - 前篇｜ていねいな田舎暮らし｜こんな暮らしがしたかった｜熊野｜地方移住｜サステナブル', description = '都会で暮らしていた頃は、「手間を惜しんで」で生きていた。
熊野に来て、ボクらの価値観は変化した。

「手間を楽しむ」

そんな、ボクらの三重県御浜町での田舎暮らし。

友人の猟師がくれたジビエで燻製を作り、お気に入りのワインを飲み、
焚き火を囲む。熊野の自然を味わったとある一日。
そんな暮らし方を教えてくれた御浜町の友人たちに感謝。

後篇はコチラから↓
https://youtu.be/Erht2-5I8Oc

三重県御浜町について、詳しくは下記Webサイトをご覧下さい↓
https://mihama-mie-townpromotion.jp/


