インスタも始めました。

Instagram: https://www.instagram.com/rural_life_japan/

#田舎暮らし #地方移住 #ruraljapan' where id = 'HkUTy7_CdQEG3t3XQxWUK';
update content_bodies set title = '[Weekend Routine] Enjoying the Effort Instead of Resenting It - Part 1 | Thoughtful Rural Living | The Life I Wanted | Kumano | Regional Relocation | Sustainable', description = 'When I lived in the city, I lived by ''cutting corners.''

Since coming to Kumano, our values have changed.

''Enjoying the effort''

This is our rural life in Mihama, Mie Prefecture.

On a certain day, we made smoked game from the wild game given to us by a friend who is a hunter, enjoyed our favorite wine, and gathered around a campfire. We savored the nature of Kumano.

I am grateful to the friends in Mihama who taught us this way of living.

The second part can be found here:
https://youtu.be/Erht2-5I8Oc

For more information about Mihama, Mie Prefecture, please visit the website below:
https://mihama-mie-townpromotion.jp/

If you have any questions, feel free to leave a comment.

If you liked it, please give us a thumbs up, comment, and subscribe to our channel. We have also started an Instagram.

Instagram: https://www.instagram.com/rural_life_japan/

