update content_bodies set title = '御浜ブルーを旅する- Blues of the Town｜熊野｜みかん｜田舎暮らし｜Japan Hidden Gems', description = '御浜は青い。

海が青い、山が青い、空が青い、風が青い、そして、みかんも青い
日本の青は不思議だ。
青信号のように、どう見ても緑色の山を青い山と呼ぶ。
そうして、このまちのみかんも青いみかんと呼ばれ親しまれている。
海沿いを自転車で走り、青い空を翔る。
9月の御浜の青は甘酸っぱい。

