update content_bodies set title = '[Weekend Routine] Enjoying the Effort - Bonfire Edition | Ideal Rural Living | Careful Living | Kumano | Regional Relocation | Sustainable', description = 'When I lived in the city, I lived by ''cutting corners.''
Since coming to Kumano, our way of life has changed to ''enjoying the effort.''
This is our rural life in Mihama, Mie Prefecture.

Making smoked game given to us by a friend who is a hunter and enjoying our favorite wine.
Having a bonfire with Kumano cedar and drinking sake infused with the aroma of Kumano cedar,
experiencing a night that feels like a journey deep into the mountains of Kumano.

I am grateful to the friends here who taught me this way of enjoying the effort.

The first part of ''Enjoying the Effort'' can be found here:

https://youtu.be/Eun1r9KEjbU

