update content_bodies set title = '【外国人移住者】山奥のフランス人 - 父の背中篇｜熊野の山奥に移住したフランス人｜自宅の山から木を切り出し、薪を作る｜熊野｜地方移住｜サステナブル', description = '山奥に住む、フランス人移住者の家族。
