update content_bodies set title = '[Foreign Immigrant] Frenchman in the Mountains - A Father''s Back | A Frenchman Who Moved to the Mountains of Kumano | Cutting Trees from His Own Mountain to Make Firewood | Kumano | Rural Relocation | Sustainable', description = 'A family of French immigrants living in the mountains.
