update content_bodies set title = '【田舎の隠れた物語】みかんに季節を重ねて暮らす｜みかんの花が咲くと、町はみかんの香りに包まれた｜熊野｜地方移住｜サステナブル', description = '都会から地方に移住した夫婦の田舎暮らしの日常。

雄大な太平洋と神秘的な紀伊山地が出会う町
年中みかんのとれるまち、三重県御浜町
御浜町のある三重県の南部は東紀州地域と呼ばれ、
温州みかんの産地。
みかんの花咲く頃に、夏の準備をされたここの温州みかんの木々は、
梅雨を越え、夏を乗り切った秋、おししく実る。
この人々のみかんに対する愛が東紀州のみかんを美味しくしているのだなと思う。今から、九月の温州みかん極早生が待ちきれない。

