update content_bodies set title = '[Ideal Rural Life] The Seventy-Three-Year-Old Cinderella - Sustainable Living Episode 3: Goemon Bath Edition | Careful Living | Kumano | Regional Relocation | Sustainable', description = 'Traveling through the daily life of the countryside.

Taking a break from my own daily life to intrude on someone else''s.
I believe that is what travel is.
Peeking into someone else''s daily life might change my own daily life the most.

