Through regional relocation and rural living, and during this COVID-19 pandemic, I have started to think about new forms of travel and living that never existed before.
With travel itself becoming difficult due to COVID, experiencing someone else''s daily life, which is different from my own, nearby is enjoyable.
Recently, I find myself pondering.

This is also a form of travel.

Today, I will visit the seventy-three-year-old Cinderella''s sustainable life at Oroshi-an, located in the Oroshi district of Mihama Town, Mie Prefecture, which has appeared before.
Cooking rice in a kamado and preparing a pot and sweetfish over an irori.
