The land of resurrection, Kumano
A town where mandarins are harvested year-round, Mihama Town, Mie Prefecture.

A town along the Pacific Ocean at the southernmost tip of the Kii Peninsula and Honshu.
Along the Pacific coastline lies the Shichiri Mihama, stretching approximately 22 km.
It has long been a beloved path of prayer for the common people, the World Heritage Site "Kumano Kodo Iseji."
Thanks to the Kuroshio Current and the warm climate, various mandarins can be harvested year-round.
With the mystical Kii Mountains and the majestic Pacific Ocean,
it is a town where mountains and the sea intersect.

Kumano has been called the "land of resurrection." Since ancient times in Japan, there has been a belief that mountains are sacred places where the spirits of gods and ancestors reside, in contrast to the villages where people live. Among them, Kumano is a sacred site of deep mountains where deities dwell, and those who visit find their spirits revived and their hearts renewed.

This is why it is said, "Life is the land of departure."
Additionally, the natural faith that has continued since prehistoric times, the mountain religion represented by Kumano Shugendo, and the belief system that sees gods and Buddhas as one have combined to create a soil that nurtures Japan''s unique religious perspective.

Quoted from the Kumano Hongu Taisha website.

