update content_bodies set title = '[Ideal Rural Living] The 73-Year-Old Cinderella - The Arrival of Cinderella｜Sustainable Ideal Living｜Kumano｜Rural Relocation｜Sustainable', description = 'This time, we visited Oroshi-an, a traditional-style experiential accommodation located in Mihama Town, Mie Prefecture, to explore the sustainable life of a 73-year-old Cinderella.
She relocated to the countryside at the age of 60 and moved to Oroshi a year and a half ago.
This is the first part of a two-part series.
While the charm of Oroshi-an as an experiential accommodation is noteworthy, her sustainable way of living serves as a guiding principle for our future rural life.

For more information about Mihama Town, please visit the website below:
https://mihama-mie-townpromotion.jp/

The Land of Resurrection, Kumano
A town in Kumano, Mihama Town, Mie Prefecture

Kumano has been referred to as the "Land of Resurrection." Since ancient times in Japan, there has been a belief that while the villages where people live are ordinary, the mountains are sacred places where gods and ancestral spirits reside. Among them, Kumano is a spiritual site where deities dwell, and those who visit find their spirits revived and their hearts renewed.
This is why it is said to be "the land of life''s new beginnings."
Additionally, the long-standing nature worship, mountain religions represented by Kumano Shugendo, and the syncretic belief that gods and Buddhas are one have fostered a unique religious perspective in Japan.

Quoted from the Kumano Hongu Taisha website
About Kumano

"Kumano is a feeling - not a form - a manifestation of the Divine Intangibles, a celebration of life''s powerful vitality.
It is a peaceful place in nature to take a moment to reflect on, and reaffirm one''s future direction and meaning of life - a sacred space to open one''s mind, heart, soul; all of one''s senses; and let the artificial boundaries and borders of the modern world disappear - allowing us to contemplate life as one unified humanity on planet earth.
The importance of a pilgrimage to Kumano is not in its completion, but rather what you take home after internalizing your experience" (Kumano Kodo, 2019).

I started searching for a relocation place in January this year, and fortunately visited Mie Prefecture, including Mihama Town, and the Wakayama and Higashi-Kishu areas just before the COVID-19 restrictions in March. However, after that, I was unable to visit the area, and due to the inability to research other locations, I decided to relocate to Mihama Town, which felt like a fateful encounter. I made the decision to relocate within about six months. It took courage to decide to move to a town with no connections or ties, especially since I had only visited for a few hours in March, but I felt that if I continued searching, it would take years to relocate, so I was able to take the plunge.

Rural Japan ♯13 Cinderella of 73 Years Old｜Sustainable Living｜Slow Living | Explore Japan | Travel Japan｜ENG SUB

Today, we’re going to visit a guest house in the Oroshi district, Mihama Town, Mie, where you can experience rural life in Japan.
Even though the guest house offers you the distinct experience of sustainable living in rural Japan,
Her life is personally much worth watching.
73-year-old Cinderella shows us the life she’s been on and what she believes in.
Sustainable Living
This concept is quite difficult to define, but we think that the life there is what we consider it to be.
Let''s see her everyday living, the sustainable living in Japan.

What kind of life are we searching for?

We are now searching for the meaning of life.
We come to see some people who show us their meaning of life in Mihama, Kumano.
Most people who moved to Kumano say Kumano has sacred power.
Once you come to visit Kumano, you would be able to understand what they are saying.
What kind of adventures are waiting for you?

We plan to upload videos two to three times a month, so if you liked it, please like, comment, and subscribe to the channel. We have also started an Instagram.

Instagram: https://www.instagram.com/rural_life_japan/

We have received a lot of help from here.

[Mihama Town Relocation and Exchange Support Desk]
If you are interested in relocating to Mihama Town, please do so. We also received assistance here.
http://mihama-iju.com/

[Kumano Relocation Network]
If you are interested in relocating to Kumano City, please do so.
Unfortunately, I relocated to the neighboring Mihama Town, not Kumano City,
but thanks to the dedicated staff, it is not an exaggeration to say that my relocation to the Higashi-Kishu area was realized.
https://kumanoijunet.jimdofree.com/

@Lyrical Rural Living

#RuralLiving #RuralRelocation #SustainableLiving' where id = 'oJsnOjdv15X5tJfFC1EUi';
update content_bodies set title = '伊勢と奈良、神話からの古代の道', description = '伊勢と奈良、神話からの古代の道

日本の起源の地、神話の時代から。日本の神道の頂点である伊勢神宮、相撲、酒、修験道、巨大な古代の墳墓など。これは、今日の政治と文化の起源を感じることができる道です。「古代日本」を体験してください。

伊勢と奈良の地域は、精神性の道を導き、日本の神秘主義の起源へと至ります。

関西の中心に位置する奈良は、日本で最も古い仏教寺院や神社で世界的に有名です。それらは、シカが生息する森林公園の中心にある緑豊かな草原に位置しています。8世紀の古代首都は、日本の政治と宗教の中心でした。奈良の計り知れない芸術的な富は、今なお彼女を精神性の大きな中心にしています。近くには、法隆寺の五重塔があり、世界最古の木造建築とされています。

聖なる土地は、神聖な山々であふれる紀伊半島まで広がっています。そこでは、百年の杉の深い森の中で、神々がほぼ二千年にわたり崇拝されてきました。伊勢神宮は、日本で最も神聖で崇敬される場所の一つです。日本人はそれを「日本の魂の揺りかご」と考えています。

寺院周辺の精神性と修験道の修行に加えて、伊勢と奈良の地域は、相撲や酒の蒸留などの古代の伝統を育んでいます。海側では、紀伊半島の沿岸で、真珠、貝、魚、甲殻類を求めてシュノーケリングをする女性たち、あま文化が生まれました。半島とその沿岸は、日本の最も古い伝統に抱かれ、集団的な想像力にとって最も印象的なものです。' where id = 'HYenAH-VlmrvuAVByddt5';
update content_bodies set title = 'ISE and NARA,Ancient paths from mythology', description = 'ISE and NARA,Ancient paths from mythology

The place of origin of Japan since mythical times. Ise Jingu, the pinnacle of Japanese Shintoism, Sumo, Sake, Shugendo, giant ancient tombs, etc. This is the path where you can feel the origin of today''s politics and culture.Experience the "ancient Japan"

The region of Ise and Nara leads on the paths of spirituality, to the origins of Japanese mysticism.

In the heart of Kansai, Nara is world famous for its Buddhist temples and Shinto shrines, some of the oldest in Japan. They are set on lush meadows, in the heart of a wooded park populated by Sika deer. The ancient capital of the 8th century was the political and religious center of Japan. Nara''s inestimable artistic wealth still makes her a great center of spirituality. Nearby, the 5-story pagoda of Hōryū-ji Buddhist temple is considered the oldest wooden building in the world.

The sacred lands extend to the Kii Peninsula, which is teeming with sacred mountains. There, in deep forests of hundred-year-old cedars, the kami have been revered for nearly two millennia. Ise-jingu (Ise Shrine) is one of the holiest and most revered sites in Japan. The Japanese consider it to be a “cradle of the Japanese soul.

In addition to the spirituality and ascetic practice of shugendō around the temples, the region of Ise and Nara cultivates ancient traditions, foremost among them sumo and the distillation of sake. On the sea side, the coasts of the Kii peninsula have seen the emergence of the culture of the ama, these women who snorkel in search of pearls, shellfish, fish and crustaceans. The peninsula and its coasts are cradled by the oldest traditions of Japan, and the most striking for the collective imagination.' where id = 'MuOgyPpLYgODLBL_FMcm9';
